import { chapter } from "./resource-chapter";

export const reactLessons = chapter("Get started", [
  {
    id: "quick-start",
    title: "Quick Start",
    summary: "Build a small React interface while learning components, JSX, data, events, and shared state.",
    level: "Beginner",
    content: [
      "React interfaces are composed from components: JavaScript functions that return UI. A component can be a small control or a full page, and you can combine components to build larger screens. Component names start with a capital letter so React can distinguish them from built-in HTML elements.",
      "Most React projects use JSX, a JavaScript syntax for describing markup. Close every tag and return one parent element, using a fragment when you do not need an extra DOM wrapper. Use className for CSS classes, and curly braces to insert JavaScript values or expressions.",
      "Use ordinary JavaScript conditions and array methods to decide what appears. Give list items stable keys from their data so React can track items when the list changes. Event handlers are passed as functions, and useState stores information that should update the screen.",
      "Hooks such as useState belong at the top level of a component or custom Hook, not inside conditions or loops. If multiple components need the same changing value, store it in their closest shared parent and pass the value and event callback down as props.",
    ],
    examples: [
      { title: "Compose components and JSX", code: "function ActionButton() {\n  return <button type=\"button\">Open lessons</button>;\n}\n\nexport default function CourseCard() {\n  return (\n    <>\n      <h2>React basics</h2>\n      <ActionButton />\n    </>\n  );\n}", result: "The page contains a heading and a reusable button component." },
      { title: "Render data, conditions, and a list", code: "const learner = { name: \"Mina\", enrolled: true };\nconst topics = [\n  { id: \"jsx\", title: \"JSX\" },\n  { id: \"state\", title: \"State\" },\n];\n\nfunction LearningPanel() {\n  return (\n    <section className=\"panel\">\n      <h2>Welcome, {learner.name}</h2>\n      {learner.enrolled ? <p>Your course is ready.</p> : <p>Choose a course.</p>}\n      <ul>{topics.map(topic => <li key={topic.id}>{topic.title}</li>)}</ul>\n    </section>\n  );\n}", result: "The greeting, enrollment message, and keyed topic list come from JavaScript data." },
      { title: "Respond to events and share state", code: "import { useState } from \"react\";\n\nfunction CountLabel({ count, onAdd }) {\n  return <button onClick={onAdd}>Added {count} times</button>;\n}\n\nexport default function SharedCounter() {\n  const [count, setCount] = useState(0);\n  function addOne() { setCount(previous => previous + 1); }\n\n  return (\n    <>\n      <CountLabel count={count} onAdd={addOne} />\n      <CountLabel count={count} onAdd={addOne} />\n    </>\n  );\n}", result: "Both controls show the same count because their parent owns the shared state." },
    ],
    quizzes: [
      { question: "Which name is valid for a custom React component?", options: ["CourseCard", "courseCard", "course-card"], answer: 0, explanation: "Custom component names begin with a capital letter." },
      { question: "How should a click handler be attached to a button?", options: ["Pass a function with onClick={handleClick}", "Call it while rendering with onClick={handleClick()}", "Put the function name in a text child"], answer: 0, explanation: "Passing the function lets React call it when the click happens." },
      { question: "Two child components need the same changing value. Where is a useful place to keep it?", options: ["In their closest shared parent, then pass it as props", "In a separate state variable inside each child", "In a JSX string"], answer: 0, explanation: "Lifting shared state to the nearest common parent keeps both children in sync." },
    ],
  },
]);

const gameTopic = (id: string, title: string, summary: string, content: string[], examples: [string, string, string], quizzes: [string, string, string]) => ({
  id, title, summary, content, level: "Beginner" as const,
  examples: examples.map((code, i) => ({ title: `Example ${i + 1}`, code, result: "Use this pattern as a building block in the game, then adapt it to your component structure." })),
  quizzes: quizzes.map((question) => ({ question, options: [question, "Keep a separate copy that can drift out of sync", "Change the rendered DOM by hand"], answer: 0, explanation: "This is the React pattern that keeps the game UI predictable." })),
});

export const ticTacToeLessons = chapter("React projects", [
  gameTopic("tic-tac-toe", "Tutorial: Tic-Tac-Toe", "Build a playable grid game, then add move history and time travel.", ["This project combines reusable components, props, state, event handlers, and list rendering. Begin with a grid of buttons, then make each button reflect game data rather than keeping its own unrelated copy.", "The board state is a nine-item array. A move creates a copied array, places the current player's mark in an empty cell, and sends the new board to the component that owns shared game state. Derived values such as the next player and winner can be calculated from that state.", "When the game ends, prevent further moves. For time travel, store each board snapshot in history and track the selected move. Selecting an earlier snapshot changes the displayed board; a new move from that point should discard later snapshots. Stable keys identify the history buttons, while the move number is suitable because these entries are sequential and do not reorder."], [
    "const emptyBoard: (\"X\" | \"O\" | null)[] = Array(9).fill(null);\n// Render nine buttons from this data with map().",
    "function play(board, index, mark) {\n  if (board[index] !== null) return board;\n  const next = board.slice();\n  next[index] = mark;\n  return next;\n}",
    "const [history, setHistory] = useState([emptyBoard]);\nconst [move, setMove] = useState(0);\nconst board = history[move];\nconst nextMark = move % 2 === 0 ? \"X\" : \"O\";"
  ], [
    "How can a board update keep the previous snapshot unchanged?",
    "Where should board state live when both the grid and status need it?",
    "What should happen to later snapshots after making a move from an earlier point?"
  ]),
  gameTopic("tictactoe-building-board", "Build the board", "Represent nine cells as a grid of reusable square buttons.", ["A game board is a visual arrangement of nine cells. Group the buttons into rows or use a grid container, and keep each cell a real button for keyboard access.", "Separate a Square component from the Board so one component handles a cell and another arranges the cells. Give each cell its position from data instead of duplicating unrelated markup."], ["function Square() { return <button type=\"button\">Empty</button>; }", "<div className=\"row\"><Square /><Square /><Square /></div>", "const cells = Array.from({ length: 9 }, (_, index) => index);\n{cells.map(index => <Square key={index} />)}"], ["What is one benefit of a Square component?", "Why use button elements for playable cells?", "What should each rendered cell receive to distinguish its position?"]),
  gameTopic("tictactoe-props", "Pass data through props", "Send a cell's value and action from the board to its child.", ["Props are inputs a parent supplies to a child. A Square can receive the mark to display and a callback to notify the board when it is pressed.", "The child renders the supplied value and calls the supplied function. Keep the authoritative board data in the parent so every square reflects the same game state."], ["function Square({ value }) { return <button>{value ?? ''}</button>; }", "<Square value={board[4]} />", "<Square value={board[4]} onPress={() => playAt(4)} />"], ["Who supplies a child's props?", "What is a good use for a callback prop?", "Why should board values have one authoritative owner?"]),
  gameTopic("tictactoe-interactivity", "Make a component interactive", "Connect cell clicks to state updates and prevent invalid moves.", ["An event handler is a function passed to an event prop such as onClick. Pass the function itself, or an arrow function when you need to include an argument.", "A click should do nothing when the game is finished or the chosen square already contains a mark. Updating state asks React to render the new game view."], ["<button onClick={handleClick}>Choose</button>", "<button onClick={() => handleCellClick(4)}>Center</button>", "function handleCellClick(i) { if (winner || board[i]) return; makeMove(i); }"], ["Should onClick usually receive handleClick or handleClick()?", "When should a move handler return without changing the board?", "What tells React to display updated state?"]),
  gameTopic("tictactoe-devtools", "Inspect a React app", "Use browser and editor tools to understand component behavior.", ["A component tree helps show which components render other components. Browser developer tools can reveal console errors and inspect rendered markup.", "When something looks wrong, trace the value from its state owner through props to the displayed element. Fix warnings such as missing list keys rather than ignoring them."], ["// Inspect the component that owns board state first.", "// Check the console for warnings after rendering a list.", "// Follow props from Game -> Board -> Square."], ["What can a component tree help you inspect?", "Where can runtime warnings appear?", "How can you trace a displayed cell value?"]),
  gameTopic("tictactoe-complete", "Complete the game", "Combine turns, move validation, and a winner message.", ["The board coordinator decides whose turn it is, rejects occupied cells, and computes whether a winning line exists. The interface can then show the winner or the next player.", "Keep game rules in small functions that accept board data. This makes the rules easier to inspect and keeps rendering code focused on the interface."], ["const lines = [[0,1,2], [3,4,5], [6,7,8]];", "function winnerOf(board, lines) { for (const [a,b,c] of lines) if (board[a] && board[a] === board[b] && board[a] === board[c]) return board[a]; return null; }", "const status = winner ? `Winner: ${winner}` : `Next: ${nextMark}`;"], ["Why separate winner calculation from markup?", "What should the UI show after a winning line appears?", "Why reject clicks on already occupied cells?"]),
  gameTopic("tictactoe-lifting", "Lift shared state", "Move the board state to the closest parent that coordinates the game.", ["If each square owns its mark, the board cannot reliably decide turns or winners. Move the board array to a shared parent and pass each child its displayed mark and event callback.", "This pattern is called lifting state up. The parent becomes the source of truth and can coordinate multiple children from one update."], ["const [board, setBoard] = useState(Array(9).fill(null));", "<Board board={board} onMove={handleMove} />", "<Square value={board[i]} onPress={() => onMove(i)} />"], ["When should state be lifted to a parent?", "What does a source of truth help avoid?", "How does a child request a state change?"]),
  gameTopic("tictactoe-immutability", "Why immutability matters", "Create new board snapshots instead of editing existing state arrays.", ["React state updates work best when the next value is a new array or object. Mutating the existing board can make changes harder to detect and corrupt earlier history snapshots.", "Copy the array before changing one cell. For nested data, copy each level that changes so earlier values stay intact."], ["const next = board.slice();", "const next = board.map((cell, i) => i === target ? mark : cell);", "const nextHistory = [...history, next];"], ["Why avoid changing a state array in place?", "Which array method can copy all cells with one changed position?", "What does immutability enable for move history?"]),
  gameTopic("tictactoe-turns", "Taking turns", "Derive the active player's mark and display whose move is next.", ["A turn value can determine which mark is placed next. Keep the rule consistent: each accepted move changes the turn once, while rejected moves change nothing.", "If the current move count is stored, the active player can be derived from whether the count is even or odd. Avoid storing duplicate values that can get out of sync."], ["const mark = move % 2 === 0 ? 'X' : 'O';", "const status = `Next player: ${mark}`;", "function handleMove(i) { if (board[i] !== null) return; commit(i, mark); }"], ["What should happen to the turn after an accepted move?", "What should happen after an invalid move?", "How can move parity determine the active mark?"]),
  gameTopic("tictactoe-winner", "Declare a winner", "Check the possible rows, columns, and diagonals for matching marks.", ["A winning line contains three equal, non-empty cells. There are eight possible lines on a three-by-three board: three rows, three columns, and two diagonals.", "Run the check after a move and block further moves if a winner is found. If all cells are filled and no line matches, the game is a draw."], ["const wins = [[0,1,2], [3,4,5], [6,7,8], [0,3,6], [1,4,7], [2,5,8], [0,4,8], [2,4,6]];", "const line = wins.find(([a,b,c]) => board[a] && board[a] === board[b] && board[b] === board[c]);", "const draw = !winner && board.every(cell => cell !== null);"], ["How many winning lines are possible on the board?", "Why must the first cell be non-empty before declaring a match?", "How can a draw be identified?"]),
  gameTopic("tictactoe-time-travel", "Add time travel", "Store past boards so a player can revisit an earlier move.", ["History is an array of board snapshots, beginning with the empty board. A selected move index tells the game which snapshot to display.", "Move buttons let the player jump to a saved snapshot. When making a new move from the past, keep history only through that selected point before appending the new board."], ["const history = [emptyBoard, afterMoveOne, afterMoveTwo];", "const currentBoard = history[currentMove];", "const nextHistory = [...history.slice(0, currentMove + 1), nextBoard];"], ["What does each history entry store?", "How does the app choose the displayed board?", "Why remove later snapshots after branching from a past move?"]),
  gameTopic("tictactoe-history", "Store a history of moves", "Track board snapshots and the currently selected step.", ["Keep the initial empty board as move zero. Each accepted move appends a new immutable snapshot, making the sequence easy to replay.", "The selected index ranges from zero through the final history entry. The active player can be derived from this index, avoiding separate turn state."], ["const [history, setHistory] = useState([Array(9).fill(null)]);", "const [currentMove, setCurrentMove] = useState(0);", "const isXNext = currentMove % 2 === 0;"], ["What should history contain at the start?", "What does currentMove represent?", "Why derive the next turn from the selected move index?"]),
  gameTopic("tictactoe-lift-again", "Lift state for history", "Let the game component coordinate board, turn, and snapshots.", ["Once history is needed, move the state from the board into a Game component. The Board receives the current snapshot, next mark, and a callback to report a move.", "This keeps the board presentational and lets Game coordinate both play and navigation through previous states."], ["<Board squares={history[currentMove]} xIsNext={currentMove % 2 === 0} onPlay={handlePlay} />", "function handlePlay(nextBoard) { setHistory(previous => [...previous, nextBoard]); }", "function jumpTo(move) { setCurrentMove(move); }"], ["Why should Game own history state?", "What does Board receive from its owner?", "How does Board report a played move?"]),
  gameTopic("tictactoe-past-moves", "Show past moves", "Render a navigable list of snapshots with clear labels.", ["Map over history to create a button for each saved step. Use a descriptive label for the start and number later moves so players know where each button goes.", "Each list item needs a key unique among its siblings. For an append-only sequential history, the move index is stable for that history."], ["const buttons = history.map((_, move) => <li key={move}><button onClick={() => jumpTo(move)}>Move {move}</button></li>);", "<ol>{buttons}</ol>", "const label = move === 0 ? 'Start' : `Go to move ${move}`;"], ["Which array method builds the move list?", "Why does each list child need a key?", "Why is a move index acceptable for sequential history entries?"]),
  gameTopic("tictactoe-keys", "Pick stable keys", "Help React preserve the identity of list items as they change.", ["Keys let React match siblings between renders. Prefer stable identifiers from data; indexes are risky when items are inserted, removed, or reordered.", "A key only needs to be unique among siblings. It is reserved for React and is not received by the component as an ordinary prop."], ["items.map(item => <li key={item.id}>{item.title}</li>)", "history.map((snapshot, move) => <Move key={move} move={move} />)", "// Pass id separately if the child needs to read it: <Row key={id} id={id} />"], ["What should a key help React identify?", "When are indexes risky as keys?", "Can a child read its key as a normal prop?"]),
  gameTopic("tictactoe-implement-time-travel", "Implement time travel", "Connect move selection to the displayed snapshot and future play.", ["A jump action updates the selected move. The board is read from history at that index, while the next player follows from its parity.", "When a new move is recorded, trim any future branch, append the new snapshot, and update the selected index to the last entry."], ["function jumpTo(move) { setCurrentMove(move); }", "const board = history[currentMove];", "function play(nextBoard) { const next = [...history.slice(0, currentMove + 1), nextBoard]; setHistory(next); setCurrentMove(next.length - 1); }"], ["What changes when selecting a past move?", "How is the next mark calculated after jumping?", "Where should the selected index point after a new move?"]),
  gameTopic("tictactoe-cleanup", "Final cleanup", "Remove redundant state and make the game's rules easy to follow.", ["If the active player is determined by the move index, storing both values creates a risk of disagreement. Keep the source data and derive values during render.", "Name handlers clearly, handle win and draw states, and keep keyboard-friendly buttons. Small pure rule functions make the finished game easier to review."], ["const xIsNext = currentMove % 2 === 0;", "const currentBoard = history[currentMove];", "const status = winner ? `Winner: ${winner}` : draw ? 'Draw' : `Next: ${xIsNext ? 'X' : 'O'}`;"], ["Why remove redundant state?", "What can be derived from currentMove?", "What should a finished game status communicate?"]),
  gameTopic("tictactoe-wrap-up", "Wrap up and extend the game", "Review the React ideas in the finished game and choose a small improvement.", ["The game brought together component composition, props, event handling, state ownership, immutable updates, list keys, and derived values.", "Extend it in small steps: show winning cells, report a draw, display row and column for each move, or let the player reverse the history list. Keep each improvement focused and verify the game after changing it."], ["const row = Math.floor(index / 3);", "const column = index % 3;", "const [ascending, setAscending] = useState(true);\nconst orderedMoves = ascending ? moves : [...moves].reverse();"], ["Name two React concepts used by the game.", "How can an index map to a row in a 3-column board?", "Why should an improvement be made in a small step?"]),
]);

export const thinkingReactLessons = chapter("React projects", [
  gameTopic("thinking-in-react", "Thinking in React", "Plan a searchable product list by shaping components, data, and state before adding interactions.", ["A strong React implementation starts by studying what the interface must show and how its data is shaped. Split the design into components with focused responsibilities, then decide which values are fixed inputs and which values change through user actions.", "Build the first version from props and data without adding state too early. Next, identify the smallest set of changing values that cannot be calculated from other values, decide which common parent should own them, and pass event callbacks down to where the interaction happens.", "For a product table, the source product list can be fixed input. Search text and an availability toggle are changing state. The visible rows are derived by filtering products, so they should be calculated during rendering instead of copied into another state variable."], ["const catalog = [{ name: 'Notebook', group: 'Paper', price: 4, available: true }];", "function ItemRow({ item }) { return <tr><td>{item.name}</td><td>{item.price}</td></tr>; }", "const visible = items.filter(item => item.name.toLowerCase().includes(query.toLowerCase()));"], ["What is a useful first step before coding a designed interface?", "Should a filtered list usually be stored separately if it can be calculated from products and query?", "Where should shared search state live if both search control and table need it?"]),
  gameTopic("thinking-mockup", "Start with the mockup", "Use a design and sample data to understand the interface before building it.", ["A mockup communicates visible regions and relationships; sample data reveals what each region needs to display. Inspect both together and note repeated patterns, category boundaries, and interactive controls.", "Treat the data model as a guide, not a rule that every field becomes a component. Build components where they clarify a responsibility or reusable part of the interface."], ["type Item = { title: string; section: string; cost: number; inStock: boolean };", "const items: Item[] = [{ title: 'Sketchbook', section: 'Art', cost: 8, inStock: true }];", "// Sketch the layout regions: filters, table headings, grouped rows."], ["What two inputs help you understand a UI before implementation?", "Does every data field need its own React component?", "Why inspect sample records as well as the visual design?"]),
  gameTopic("thinking-hierarchy", "Step 1: Break the UI into components", "Turn the interface into a small, understandable component tree.", ["Name the major areas first, then split a region further when it has a clear task or repeated structure. A searchable table might have a page container, filter controls, a table, group headings, and individual rows.", "Arrange components according to what appears inside what. Use the same decomposition to make ownership and data flow easier to reason about."], ["function CatalogPage() { return <><Filters /><ItemTable /></>; }", "function ItemTable({ items }) { return <table><tbody>{items.map(item => <ItemRow key={item.id} item={item} />)}</tbody></table>; }", "function GroupHeading({ label }) { return <tr><th colSpan={2}>{label}</th></tr>; }"], ["How should components in a hierarchy relate to the visual layout?", "What is one reason to extract a repeated row component?", "Should every tiny element automatically become a component?"]),
  gameTopic("thinking-static", "Step 2: Build a static React version", "Render the complete layout from data and props before wiring up controls.", ["A static version confirms the component tree, markup, and data flow without state transitions. Parent components pass the data that child components need through props.", "Starting without interactive state makes layout and rendering problems easier to isolate. Once the UI displays the right data, add the controls that change it."], ["function ItemRow({ item }) { return <p>{item.title}: ${item.cost}</p>; }", "function ItemList({ items }) { return <ul>{items.map(item => <li key={item.id}><ItemRow item={item} /></li>)}</ul>; }", "function Catalog({ items }) { return <main><h1>Catalog</h1><ItemList items={items} /></main>; }"], ["What should a static version prove?", "How does a parent provide data to a child?", "Why can delaying state make early debugging easier?"]),
  gameTopic("thinking-state", "Step 3: Find the minimal UI state", "Store only values that change and cannot be derived from existing data.", ["State is for information that changes over time because of interaction or external updates. A value that can be calculated from props and existing state is derived data and usually should not be duplicated in state.", "For a filterable list, the original items are input data; the search phrase and checkbox setting can be state. The visible list is calculated from those values."], ["const [query, setQuery] = useState('');", "const [onlyAvailable, setOnlyAvailable] = useState(false);", "const shown = items.filter(item => item.title.includes(query) && (!onlyAvailable || item.available));"], ["Which values are good candidates for state?", "Why avoid storing a second copy of visible items?", "What can be derived from items and query?"]),
  gameTopic("thinking-state-location", "Step 4: Decide where state should live", "Place each state value at the lowest shared owner that needs to coordinate it.", ["A state value belongs in the closest common ancestor of the components that read or update it. That owner can pass values down and callbacks up through props.", "If only one component needs a value, keep it local. If siblings need the same value, lift it to their shared parent rather than maintaining independent copies."], ["function CatalogPage({ items }) { const [query, setQuery] = useState(''); return <><SearchBox value={query} onChange={setQuery} /><ItemTable items={items} query={query} /></>; }", "<SearchBox value={query} onChange={setQuery} />", "<ItemTable items={items} query={query} />"], ["What is a useful home for state used by sibling components?", "When can state remain inside one component?", "How does a parent share updated state with children?"]),
  gameTopic("thinking-inverse-flow", "Step 5: Add inverse data flow", "Let child controls notify the state owner through callback props.", ["Data typically flows from a parent to children through props. To report an interaction back, the parent passes a callback that the child calls with the new value.", "This keeps state ownership clear: the child reports what happened, and the owner decides how to update the state. Use event handlers to connect input changes to the callback."], ["function SearchBox({ value, onChange }) { return <input value={value} onChange={event => onChange(event.target.value)} />; }", "<SearchBox value={query} onChange={setQuery} />", "function StockFilter({ checked, onToggle }) { return <label><input type=\"checkbox\" checked={checked} onChange={event => onToggle(event.target.checked)} /> Available only</label>; }"], ["What does a callback prop let a child do?", "Who should decide how shared state changes?", "What direction does the callback notification travel?"]),
  gameTopic("thinking-next", "Where to go from here", "Use the same component, data, and state planning process on new interfaces.", ["The method applies to dashboards, forms, galleries, and other data-driven screens: inspect the design and data, choose a component tree, render a static view, then add minimal state and interactions.", "As an app grows, keep components focused and state close to its consumers. Revisit the structure when a new feature changes which components must coordinate."], ["// For a gallery: PhotoGrid -> PhotoCard", "// For a form: FormPage -> FieldGroup -> Field", "// Derive filtered photos from photos plus selectedTag."], ["What can be reused from this planning method on another app?", "Where should state stay when only one small component needs it?", "When should a component structure be revisited?"]),
]);

export const reactInstallationLessons = chapter("Get started", [
  gameTopic("react-installation", "Installation", "Choose a way to try React, start an app with Next.js, or add React to an existing site.", ["React can be adopted in different ways. You can experiment in a browser sandbox, create a new app with a framework such as Next.js, build a small custom setup for learning, or add React to part of an existing page.", "For a new React website, Next.js gives you routing, rendering, development tools, and a project structure. You need Node.js installed, then create a project, enter its folder, start the development server, and open the local address shown in the terminal.", "The commands below use npm. During setup, choose options that fit the project; recommended defaults are a good starting point. To add React to an existing app, first check its build system and follow an integration path compatible with it. Create React App is deprecated, so use a maintained framework or a deliberate custom setup."], ["// Try a component in a browser sandbox\nfunction Greeting({ name }) { return <h1>Hello, {name}</h1>; }", "// Create a Next.js app\nnpx create-next-app@latest my-react-app\ncd my-react-app\nnpm run dev", "// Open the local site after the server starts\n// Visit http://localhost:3000\n// Stop the server with Ctrl+C in the terminal"], ["What should be installed before creating a Next.js project?", "Which command starts the local development server in this npm setup?", "Why is Create React App not recommended for a new project?"]),
  gameTopic("react-try", "Try React", "Experiment with components in an online sandbox before installing tools.", ["A browser sandbox can provide a quick place to edit a component and see its output. It is useful for short experiments and sharing a small reproduction.", "Try changing component props, markup, or simple styles. For a larger app, move to a local project so you can use files, dependencies, and version control."], ["function Greeting({ name }) { return <h1>Hello, {name}!</h1>; }", "function App() { return <Greeting name=\"Ari\" />; }", "function Badge({ count }) { return <span>{count} new items</span>; }"], ["What is a browser sandbox useful for?", "What is one thing you can change to experiment with a component?", "When is a local project more useful than a quick sandbox?"]),
  gameTopic("react-create-app", "Create a React app with Next.js", "Scaffold a new React project with routing and development tools included.", ["Next.js is a React framework that supplies app structure and features beyond rendering components. Its CLI can create a ready-to-run project and guide choices such as TypeScript, styling, and routing.", "Install a supported Node.js version first. Run the create command from a terminal, choose a project name and setup options, enter the created directory, and start the dev server. Keep the terminal running while you open the local URL it reports."], ["npx create-next-app@latest study-hub", "cd study-hub\nnpm run dev", "// Edit app/page.tsx, save, and view the refreshed page at localhost:3000"], ["What does create-next-app create?", "Why does the development terminal stay open?", "Where can you edit the home page in the default App Router setup?"]),
  gameTopic("react-build-from-scratch", "Build a React app from scratch", "Understand the pieces needed for a custom React setup.", ["A from-scratch setup can help you learn how React connects to a browser, but you must choose and configure the bundler, HTML entry, scripts, and dependencies yourself.", "Install React and React DOM along with a build tool that understands JSX. Add a root element to the HTML page and render your app into it. For production apps, a framework often saves setup work and provides routing and rendering patterns."], ["npm install react react-dom", "import { createRoot } from 'react-dom/client';\ncreateRoot(document.getElementById('root')).render(<App />);", "// package scripts might run the chosen dev server and production build"], ["What additional responsibility comes with a custom setup?", "What does createRoot connect?", "Why might a framework be a better fit for a full production site?"]),
  gameTopic("react-existing-project", "Add React to an existing project", "Introduce React into a site gradually when a full rewrite is unnecessary.", ["React can power one interactive region while the rest of a site stays as it is. First identify the page element that will host the React root and check how the current site builds JavaScript.", "Add compatible React packages and configure the existing build tool to process JSX. Render a small component into the chosen container, then expand only when it helps the product. Avoid mounting multiple roots over the same DOM region."], ["<div id=\"account-widget\"></div>", "const root = createRoot(document.getElementById('account-widget'));\nroot.render(<AccountWidget />);", "// Keep server-rendered page sections outside the React root intact."], ["Can React be added to only one page region?", "What does the root container identify?", "Why should a React root not overwrite unrelated page content?"]),
  gameTopic("react-install-next-steps", "Next steps", "Choose the next learning task based on the setup you created.", ["After setup, learn components, JSX, props, state, and event handling. In a framework project, also understand its routing and server/client component model before adding app features.", "Keep your dependencies and scripts in the project manifest, save work in version control, and run the development server as you make small changes."], ["// Try a reusable component with a typed or plain-JS prop.", "// Add a button whose event updates visible state.", "// Create a new route using the framework's routing conventions."], ["Which React ideas are useful to learn after setup?", "Why follow the framework's routing conventions?", "What is a good way to learn while building?"]),
]);

export const creatingReactAppLessons = chapter("Get started", [
  gameTopic("creating-react-app", "Creating a React App", "Choose a project foundation that fits your site, app, or learning goal.", ["For a new production app, begin with a React framework when its routing, rendering, and deployment approach fits your needs. A framework provides connected decisions that would otherwise need to be chosen and maintained separately.", "A framework does not always mean a continuously running server is required. Client-rendered and statically generated output can be hosted on static infrastructure; server features are available when the project needs them. Choose based on actual routes and data needs.", "Starting from scratch can be useful for learning or special constraints, but you will select and connect tools for bundling, routing, and data loading. In the steps below Next.js App Router is used for a web project; React Router is another web option, and Expo is intended for cross-platform native interfaces."], ["npx create-next-app@latest study-space", "npx create-react-router@latest", "npx create-expo-app@latest"], ["Why can a framework help with a new application?", "Does a React framework always require a server for every deployment?", "Which option is oriented toward Android and iOS apps?"]),
  gameTopic("creating-full-stack-frameworks", "Full-stack frameworks", "Understand the integrated features frameworks provide for production apps.", ["Frameworks connect React rendering with routing, build tooling, and common application needs. This gives a project a coherent starting structure and a path to deploy.", "Some frameworks support multiple rendering approaches, including client rendering and static output, with server rendering available where useful. Select a deployment mode that matches the app's behavior and hosting limits."], ["// Route-based app: define a page for each URL in the framework's conventions.", "// Static site: prebuild pages and serve generated files from static hosting.", "// Hybrid app: use server rendering for selected routes when request-time data is needed."], ["What kinds of concerns can a framework integrate?", "Can static output be hosted without a running app server?", "Why might a project mix rendering approaches by route?"]),
  gameTopic("creating-nextjs", "Create with Next.js App Router", "Scaffold and run a React website using the Next.js App Router.", ["Next.js App Router organizes routes with files inside the app directory and includes conventions for layouts and pages. The create-next-app command scaffolds a project and asks about options such as TypeScript and styling.", "Install Node.js first, then run the CLI from a terminal and choose a project folder. Enter it, run the development script, and open the local URL printed in the terminal. The root layout and home page are the first useful files to inspect.", "As you add routes, follow the installed Next.js version's conventions. Dynamic route parameters and some rendering APIs differ across releases, so use the documentation installed with the project when building pages."], ["npx create-next-app@latest study-space", "cd study-space\nnpm run dev", "// Add a route at app/about/page.tsx\nexport default function AboutPage() { return <main><h1>About</h1></main>; }"], ["What folder convention defines App Router pages?", "What command starts the local server in a new npm project?", "Why check documentation for the installed Next.js version?"]),
  gameTopic("creating-react-router", "Create with React Router", "Use a route-focused React framework setup for URL-driven pages.", ["A routing framework maps URL paths to UI and provides conventions for navigation and data behavior. Create its starter project, then follow the generated setup instructions and understand the routes it creates.", "Keep route components focused and use the framework's recommended data and navigation APIs. A route should have a useful loading, success, and error experience when it depends on remote data."], ["npx create-react-router@latest route-demo", "cd route-demo\nnpm install\nnpm run dev", "// Add or edit route modules according to the generated project's conventions."], ["What does a router connect to a route?", "Why use the generated project instructions?", "What states should a data-backed route consider?"]),
  gameTopic("creating-expo", "Create with Expo", "Start a React Native project for mobile and other supported platforms.", ["Expo provides a development workflow around React Native, whose interface uses native building blocks rather than ordinary browser DOM elements. It can target mobile platforms and also support web.", "Create the project with its CLI, install the generated dependencies, then run the development command and follow its device or simulator options. Test on the platforms your app intends to support."], ["npx create-expo-app@latest field-notes", "cd field-notes\nnpm run start", "// Use a React Native View and Text for native interface structure."], ["Does React Native render ordinary HTML div elements on mobile?", "What does the Expo starter command create?", "Why test on intended target platforms?"]),
  gameTopic("creating-other-frameworks", "Explore other frameworks", "Evaluate newer tools by their capabilities and project fit.", ["Frameworks continue to evolve. When evaluating an alternative, compare its stability, routing, rendering, data APIs, deployment targets, community support, and maintenance needs.", "Do not choose a tool only because a feature list is long. Make a small proof of concept for the app's most important requirement and check whether the workflow is clear."], ["// Compare route and data-loading patterns in a tiny prototype.", "// Check supported hosting targets before choosing a runtime.", "// Record trade-offs: stability, team familiarity, and maintenance."], ["What should you compare when selecting a framework?", "Why build a small proof of concept?", "Should a long feature list alone decide the framework choice?"]),
  gameTopic("creating-from-scratch", "Start from scratch", "Build a custom React setup when learning or special requirements justify the extra choices.", ["A custom setup gives control, but you must assemble the development server, bundler, JSX transformation, entry point, routing, and data patterns. Treat these as real project responsibilities.", "A tool such as Vite can provide a lightweight client-side starting point. Add routing only when needed and document how development and production builds work. For a full app, compare this ongoing setup work with a framework first."], ["npm create vite@latest my-react-ui -- --template react", "cd my-react-ui\nnpm install\nnpm run dev", "// Add a router package only if the app needs multiple client-side routes."], ["What control does a from-scratch setup provide?", "What responsibilities must the team still choose?", "Why compare the custom setup with a framework before committing?"]),
]);

export const scratchReactLessons = chapter("Get started", [
  gameTopic("build-react-from-scratch", "Build a React app from Scratch", "Set up a client-side React app yourself and plan the supporting tools it will need.", ["A custom setup can be useful for learning or for requirements that a framework does not meet. You gain control, but also take responsibility for bundling, routing, data loading, deployment, and rendering choices.", "Start with a build tool that provides a development server and production build. Then add common application patterns one at a time. Keep the initial app small, and make deliberate choices before adding a router, data cache, or server rendering."], ["// Choose a build tool, create a project, and run its development command.", "// Add a router only when the app needs URL-based pages.", "// Write down build, test, and deployment steps for teammates."], ["What is the main trade-off of a from-scratch React setup?", "What does a build tool usually provide?", "Why add common app patterns one at a time?"]),
  gameTopic("scratch-install-tool", "Step 1: Install a build tool", "Use a build tool to run JSX during development and package the app for release.", ["A build tool starts a local development server and transforms source files into browser-ready assets. It can also create optimized output for deployment.", "Choose a tool that fits the team's familiarity, plugin needs, and project size. The examples here show common starter commands; follow the generated setup's scripts once the project exists."], ["npm create vite@latest my-ui -- --template react-ts", "npx create-rsbuild@latest --template react", "npm install --save-dev parcel"], ["What is one job of a build tool?", "Why check the scripts created by a starter?", "Which example creates a React TypeScript template with Vite?"]),
  gameTopic("scratch-vite", "Vite", "Start a React project with a fast development server and production build workflow.", ["Vite offers a lightweight development setup with a quick feedback loop and a production build command. A starter template can configure React and TypeScript for you.", "Create the project, install dependencies if prompted, then run its dev script. Keep app code in source files and use the production build to generate deployable static assets."], ["npm create vite@latest studio-ui -- --template react-ts", "cd studio-ui\nnpm install\nnpm run dev", "npm run build"], ["What does the Vite dev command start?", "What does the build script produce?", "Why might a React TypeScript template be helpful?"]),
  gameTopic("scratch-parcel", "Parcel", "Use a bundler that can handle common web assets with a small amount of setup.", ["Parcel can bundle JavaScript, styles, and other assets while providing a development workflow. Its configuration can grow with the application when special behavior is needed.", "Install it in the project and define the entry file and scripts. Check the chosen setup's current requirements for HTML, JSX, and TypeScript rather than assuming every project uses the same defaults."], ["npm install --save-dev parcel", "// package.json script example: \"dev\": \"parcel src/index.html\"", "// package.json script example: \"build\": \"parcel build src/index.html\""], ["What kinds of files can a bundler process?", "Where can project-specific start commands be defined?", "Why verify the tool's setup requirements?"]),
  gameTopic("scratch-rsbuild", "Rsbuild", "Create a React setup using a build tool with React-focused defaults.", ["Rsbuild provides a project build and development workflow with React support. A starter template can reduce manual configuration for JSX and common development features.", "Use its CLI to scaffold a project, then inspect the resulting scripts and configuration. Keep configuration changes documented so upgrades remain understandable."], ["npx create-rsbuild@latest --template react", "cd my-project\nnpm install\nnpm run dev", "npm run build"], ["What can a starter template configure for you?", "Why inspect generated configuration?", "Which script commonly creates production output?"]),
  gameTopic("scratch-routing", "Routing", "Map browser URLs to screens and handle navigation state.", ["A router connects URL paths to components. Real apps may also need nested pages, route parameters, query strings, not-found screens, and navigation that works with browser history.", "Choose a router that fits how the app loads data and renders routes. Keep route definitions clear and make links usable with normal browser navigation."], ["const routes = [{ path: '/', element: <HomePage /> }, { path: '/courses/:id', element: <CoursePage /> }];", "// Read a query string with URLSearchParams", "// Show a not-found view when no route matches"], ["What does a router connect?", "What is a route parameter used for?", "Why should an app handle unmatched paths?"]),
  gameTopic("scratch-data-fetching", "Data fetching", "Load remote data while showing useful loading and error states.", ["Network requests can take time or fail. A user interface should represent loading, success, empty, and error states instead of assuming data arrives immediately.", "Caching and request deduplication can prevent repeated work. For larger apps, use a data library or router loader that supports the app's needs; validate server responses before trusting them."], ["const [status, setStatus] = useState('loading');", "try { const response = await fetch('/api/courses'); if (!response.ok) throw new Error('Request failed'); } catch { setStatus('error'); }", "// Render a loading message, result list, empty state, or retry action."], ["Which states should a network-backed view consider?", "Why check response.ok?", "Why can caching help an application?"]),
  gameTopic("scratch-code-splitting", "Code-splitting", "Load some app code only when the user needs that feature.", ["Code splitting divides a large app into smaller files that can be requested when needed. Splitting by route can keep the initial download smaller for visitors who open only one area.", "Lazy loading can add a wait when a feature is first opened, so provide a useful loading state and avoid splitting tiny modules without a reason. Coordinate data and code loading to avoid unnecessary sequential waits."], ["const Reports = lazy(() => import('./Reports'));", "<Suspense fallback={<p>Loading reports…</p>}><Reports /></Suspense>", "// Split large, rarely visited routes rather than every small component."], ["What is a goal of code splitting?", "What should a lazy feature show while loading?", "Why might splitting every tiny module be unhelpful?"]),
  gameTopic("scratch-performance", "Improve application performance", "Measure real bottlenecks and choose rendering strategies carefully.", ["Start by measuring load and interaction behavior. Reduce unnecessary work, oversized assets, and dependencies before adding complex optimizations.", "Client rendering is often simplest for an interactive app. Static generation or server rendering can help routes that benefit from prebuilt or request-time HTML, but add setup and hosting needs. Choose per route when possible."], ["// Measure a slow route before changing its architecture.", "// Compress and size images for the displayed dimensions.", "// Consider static output for content that rarely changes."], ["Why measure before optimizing?", "When can static generation be a good fit?", "What trade-off can server rendering introduce?"]),
  gameTopic("scratch-more-patterns", "Plan for more application needs", "Recognize when the custom setup is becoming a framework-sized responsibility.", ["Applications may also need authentication, forms, accessibility, testing, security updates, error reporting, and deployment automation. These concerns connect to routing and data loading choices.", "Write down what the app needs now and what it may need soon. If many pieces require custom glue, compare the maintenance cost with adopting a framework."], ["// Checklist: routing, data, tests, accessibility, deployment", "// Add error boundaries or route-level recovery where useful", "// Review dependencies and update them regularly"], ["Name two concerns beyond rendering components.", "Why are routing and data loading connected?", "When should you reconsider a custom setup?"]),
]);

export const existingProjectLessons = chapter("Get started", [
  gameTopic("add-react-existing", "Add React to an Existing Project", "Introduce React to an existing site a section at a time, without replacing everything.", ["React can power one interactive area or a whole section of an existing website. Keep the parts that already work, and decide where React adds useful interactivity before changing the build setup.", "For a complete section of routes, build a React application that can live under a chosen URL prefix and configure the web server to send those requests to it. For one widget on an existing page, install React and React DOM in a modular JavaScript setup, put a dedicated container in the page, and mount a React root there.", "Keep React's container separate from server-rendered or legacy content. Do not erase the page HTML to mount a widget. If integrating into a native mobile app, React Native uses native views and needs a platform-specific integration plan rather than browser DOM roots."], ["// Existing page keeps its content around a React mount point\n<div id=\"account-widget\"></div>", "import { createRoot } from 'react-dom/client';\nconst host = document.getElementById('account-widget');\nif (host) createRoot(host).render(<AccountWidget />);", "// Route a subpath such as /workspace/* to the React application in server configuration."], ["Does adding React require rewriting the whole existing site?", "What should a widget mount into?", "Why should existing page markup remain outside the React mount point?"]),
  gameTopic("existing-subroute", "Use React for an entire subroute", "Serve a React-powered area under a path on a larger existing website.", ["A subroute approach lets an existing site keep its current stack while a new area uses a React framework. Decide on a URL prefix and configure both the app and web server to agree on it.", "Test direct visits and refreshes on nested paths, as well as links back to the main site. If the section is exported as static files, configure the server to serve those files under the same prefix."], ["// Planned path ownership: /portal/* -> React application", "// Configure the React app's base path to /portal", "// Verify direct load: /portal/settings/profile"], ["What should the server do with requests under the subroute?", "Why must the app and server agree on the base path?", "What navigation case should be tested besides clicking links?"]),
  gameTopic("existing-part-page", "Use React for part of a page", "Mount an interactive component inside selected markup from the current site.", ["A React widget can live alongside server-rendered HTML or another frontend library. Give the widget a unique container and mount a root into that specific element.", "Pass initial data through a clear boundary such as serialized page data or a module import. Avoid taking over DOM nodes that another system owns, and plan how the widget is removed or updated if the page is dynamic."], ["<section><h2>Account</h2><div id=\"account-widget\"></div></section>", "const node = document.getElementById('account-widget');\nif (node) createRoot(node).render(<AccountWidget />);", "// Keep the surrounding heading and page layout managed by the existing site."], ["What does a mount container mark?", "Can React and existing HTML coexist on one page?", "Why avoid taking over DOM that another system controls?"]),
  gameTopic("existing-modular-js", "Step 1: Set up modular JavaScript", "Use imports, JSX transformation, and package management in the existing project.", ["React components are easier to organize in modules. A build setup handles imports, JSX syntax, and packages so the browser receives code it can run.", "If the project already has a bundler, extend its configuration carefully. Otherwise, add a suitable tool such as Vite and verify that a small JSX component builds before moving more code."], ["npm install react react-dom", "// Create Widget.jsx and export a component from it.", "// Import the widget from the page entry module after JSX support is configured."], ["What does a JavaScript build setup do with JSX?", "When should an existing bundler be reused?", "What is a useful first check after configuring the tool?"]),
  gameTopic("existing-render-components", "Step 2: Render components on the page", "Connect a React root to a dedicated element without replacing unrelated content.", ["Use createRoot from react-dom/client for a client-rendered widget. Find a dedicated host element, check it exists, then render the component into that host.", "Each host element should have one React root owner. Keep surrounding page markup untouched, and unmount the root if your page lifecycle removes the widget."], ["import { createRoot } from 'react-dom/client';", "const host = document.querySelector('#search-widget');\nif (host) createRoot(host).render(<SearchWidget />);", "// Do not assign to document.body.innerHTML to make room for React."], ["Which API creates a client-side React root?", "Why check that the host element exists?", "What should be avoided when mounting inside an existing page?"]),
  gameTopic("existing-react-native", "Add React Native to an existing mobile app", "Plan a native React surface that can be integrated into a larger mobile product.", ["React Native renders native interface elements, so its integration differs from mounting React into an HTML page. A team needs platform build configuration and a clear boundary between the native app and the React Native screen.", "Start with a small screen or feature, follow the platform's native integration steps, and test navigation, startup, and data exchange with the existing app. Avoid assuming browser DOM APIs are available inside native components."], ["// Native component structure uses View and Text, not HTML div and p.", "// Define which screen or navigation entry opens the React Native feature.", "// Test data and navigation crossing between native and React Native code."], ["How does React Native rendering differ from a web React widget?", "Why start with a limited native screen integration?", "Which behavior should be checked across the integration boundary?"]),
]);

export const reactSetupLessons = chapter("Get started", [
  gameTopic("react-setup", "Setup", "Prepare an editor and tools that make React projects easier to build and inspect.", ["A React setup usually includes an editor, a project build tool, and a browser. These tools help you write components, catch mistakes, and see how the app behaves.", "Choose tools that match the project instead of installing everything at once. Add TypeScript or debugging tools when they help the work, and keep the setup steps documented so the project is easy to run again."], ["// Open the project folder in your editor.", "npm run dev", "// Keep the browser console open while checking a feature."], ["What are three common parts of a React development setup?", "Why document setup steps?", "Should every optional tool be installed before it is needed?"]),
  gameTopic("react-editor-setup", "Editor Setup", "Choose an editor and set up linting and formatting to make React work easier to read and maintain.", ["Editors such as VS Code, WebStorm, Sublime Text, and Vim can all support React development. Look for JSX and TypeScript highlighting, useful autocomplete, navigation, and a comfortable way to run project commands; choose the editor that fits your workflow.", "A linter checks code for likely mistakes and patterns that can cause bugs. In React projects, keep the Hooks rules enabled because they catch unsafe Hook usage. Linting helps find problems, while formatting tools handle consistent layout such as indentation and quotes.", "A formatter such as Prettier can apply shared style automatically. Configure format-on-save if the project supports it, and avoid conflicting formatting rules between the linter and formatter. Use the repository's existing configuration so everyone gets the same result."], ["// ESLint checks code patterns and reports likely problems.\nfunction Panel() { return <section />; }", "// Prettier formats JSX consistently.\nconst card = { title: 'React', active: true };", "// Example editor setting in settings.json\n{ \"editor.formatOnSave\": true }"], ["Name two features that can help when choosing an editor.", "What kind of issue does a linter look for?", "Why should a team share formatter settings?"]),
  gameTopic("react-typescript-setup", "Using TypeScript", "Add types to React props, state, and event handlers when they make code clearer.", ["TypeScript can describe component inputs and application data so many mismatches are caught while editing or building. React projects use TSX files when a file contains both TypeScript and JSX.", "Let inference handle straightforward values and add explicit types where the intended shape is unclear. Types do not validate server responses at runtime, so check untrusted data before using it."], ["type GreetingProps = { name: string };\nfunction Greeting({ name }: GreetingProps) { return <h1>Hello {name}</h1>; }", "const [count, setCount] = useState<number>(0);", "function handleChange(event: React.ChangeEvent<HTMLInputElement>) { console.log(event.currentTarget.value); }"], ["What file extension commonly supports TypeScript with JSX?", "What can a props type describe?", "Do TypeScript declarations validate external data at runtime?"]),
  gameTopic("react-devtools", "React Developer Tools", "Inspect components and performance in web and React Native apps.", ["React Developer Tools helps you explore a React component tree, inspect props and state, and investigate rendering performance. It adds Components and Profiler panels to supported browser developer tools when it detects a React app.", "For a browser, install the extension that matches your browser, then open the site's developer tools and select the React panels. If an extension is unavailable, the standalone package can run from a terminal and connect to a local development app when configured. Keep debugging connections limited to your own development environment.", "React Native has its own integrated debugging tools that include React component inspection. Use the debugger intended for the installed React Native version, since older projects may need a different connection method."], ["// Browser: open DevTools, then inspect the Components tree.", "// Browser: record an interaction in Profiler to inspect render work.", "npm install -g react-devtools\nreact-devtools"], ["Which panels can the browser extension add?", "What does the Profiler help investigate?", "Why should a standalone debugging connection be limited to development?"]),
  gameTopic("react-devtools-browser", "Browser extension", "Use the browser developer tools panels to inspect a React website.", ["Install the extension for the browser you use, then open developer tools on a page running React. The Components panel shows the component tree and selected component values.", "The Profiler records rendering work during an interaction. Use it to investigate a measured slowdown and identify components worth examining."], ["// Select a component in the Components panel.", "// Inspect a prop to see what data reached the component.", "// Start a Profiler recording, perform one action, then stop and review."], ["What does the Components panel display?", "What can you inspect on a selected component?", "What is a useful way to profile a slowdown?"]),
  gameTopic("react-devtools-standalone", "Standalone DevTools", "Connect the standalone inspector when a browser extension is not the right option.", ["The standalone DevTools package can be installed with a package manager and started from a terminal. A development app must be configured to connect to the local inspector.", "Use the connection setup only on a machine and project you control. Avoid adding a local debugging script to a public production page, where it could expose development details or fail for visitors."], ["npm install -g react-devtools", "react-devtools", "// Configure the local app's development entry to connect to the inspector."], ["How is the standalone inspector started?", "What must the app do to connect?", "Why should local inspector scripts stay out of public production pages?"]),
  gameTopic("react-devtools-native", "Mobile: React Native", "Inspect native React interfaces with the debugger provided for the project version.", ["React Native debugging tools support inspecting the React component tree while the interface is rendered with native platform elements. This workflow differs from browser DOM inspection.", "Use the tools supported by the app's installed React Native version. Check the version before following setup instructions, especially for older projects."], ["// Open the React Native developer menu for the running app.", "// Launch its supported debugger and inspect components.", "// Test component selection on the target simulator or device."], ["Does a React Native app render browser DOM elements?", "Why should debugging tools match the project version?", "What should you test after connecting the debugger?"]),
  gameTopic("react-compiler-setup", "React Compiler", "Understand compiler optimization and adopt it carefully in a React project.", ["React Compiler analyzes component code and can automatically apply memoization where safe. This can reduce the need to manually add useMemo, useCallback, or React.memo for performance reasons.", "It does not change how state, props, or rendering work, and it cannot fix inefficient algorithms or slow network requests. Compiler support and setup depend on the framework and versions in the project, so use the project's own build configuration and diagnostics."], ["// Write a component with clear props and state first.", "// Profile before and after enabling compiler support.", "// Keep manual memoization only when it has a clear purpose."], ["What kind of work can React Compiler automate?", "Does it change React's state model?", "What should guide performance decisions after enabling it?"]),
  gameTopic("react-setup-next-steps", "Next steps", "Use the tools to continue learning React through small, observable changes.", ["After the environment is ready, practice components, props, JSX, events, state, and lists. Make one small change at a time so you can connect the code to the result on screen.", "Use the editor and browser tools to follow values through the component tree. When the project uses TypeScript or a compiler, learn the team's checks and configuration alongside the React concepts."], ["// Change a prop and observe the rendered result.", "// Add a button that updates one piece of state.", "// Run the project's type-check and build scripts after a change."], ["What is a helpful way to practice after setup?", "Which tools can help trace a value through components?", "Why learn the project's scripts and configuration?"]),
]);

export const reactTypeScriptLessons = chapter("Get started", [
  gameTopic("react-using-typescript", "Using TypeScript with React", "Type component inputs and Hook values so React code is easier to check and understand.", ["TypeScript works with React by describing the shapes of props, state, and events. Files containing JSX use the .tsx extension, and React projects need the React type definitions as development dependencies.", "For an existing app, install the type packages, configure JSX support in tsconfig, and migrate one component at a time. In Next.js projects, TypeScript setup is already supported; follow the existing project configuration and type-check script.", "Types catch many mistakes while editing, but they do not validate network data at runtime. Keep types focused on clear contracts and validate untrusted values before treating them as a known shape."], ["npm install --save-dev @types/react @types/react-dom", "type ButtonProps = { label: string; disabled?: boolean };\nfunction Button({ label, disabled = false }: ButtonProps) { return <button disabled={disabled}>{label}</button>; }", "// JSX component file extension: ProfileCard.tsx"], ["Which file extension is used for TypeScript files containing JSX?", "What do React prop types describe?", "Do TypeScript types validate API responses while the app is running?"]),
  gameTopic("react-ts-install", "Install TypeScript support", "Add React declarations and compiler settings to a project that needs TypeScript.", ["Framework starters often offer TypeScript as a setup option. In an existing project, install React's type declarations and ensure the compiler understands DOM types and JSX.", "Use the framework's established configuration where possible. Check the project's type-check command after changing settings."], ["npm install --save-dev typescript @types/react @types/react-dom", "// tsconfig: { \"compilerOptions\": { \"jsx\": \"preserve\", \"strict\": true } }", "npx tsc --noEmit"], ["What are @types/react packages for?", "Which compiler option controls JSX transformation behavior?", "What does tsc --noEmit check?"]),
  gameTopic("react-ts-existing", "Add TypeScript to a React project", "Move an existing app gradually without replacing its whole codebase.", ["A gradual migration lets JavaScript and TypeScript modules coexist when the build tool supports it. Start with a small component or utility, then type its inputs and important data boundaries.", "Keep changes incremental and avoid using any to silence every issue. Use unknown for uncertain values and narrow them after checking."], ["// Rename one JSX component from Widget.jsx to Widget.tsx", "type WidgetProps = { title: string };", "// Keep older .js modules while migrating a small feature."], ["Can JS and TS files coexist during migration?", "Why migrate one feature at a time?", "What is a safer starting point than broad any types?"]),
  gameTopic("react-ts-components", "TypeScript with React components", "Describe props with inline types, aliases, or interfaces.", ["A prop type documents what a component expects and lets TypeScript check its callers. Optional properties use ?, and callback props should describe their parameters and return value.", "Use an inline type for tiny components and a named type for larger or reused contracts. TypeScript checks the shape at build time, while React still receives ordinary JavaScript values."], ["function Tag({ text }: { text: string }) { return <span>{text}</span>; }", "type CardProps = { title: string; onOpen: () => void };", "interface ProfileProps { name: string; bio?: string }"], ["What does an optional prop marker indicate?", "When can a named props type improve readability?", "What does a callback prop type describe?"]),
  gameTopic("react-ts-usestate", "Type useState", "Let state infer its type or supply a union when values can vary.", ["useState can infer a type from its initial value. When a state value can be empty at first and filled later, explicitly represent both possibilities.", "Keep the state type aligned with the values updates actually provide. Avoid widening everything to any."], ["const [count, setCount] = useState(0);", "const [user, setUser] = useState<User | null>(null);", "const [filter, setFilter] = useState<'all' | 'new'>('all');"], ["When can useState infer its type?", "How can a state variable represent not-yet-loaded data?", "Why use a literal union for a small set of filter choices?"]),
  gameTopic("react-ts-usereducer", "Type useReducer", "Type reducer actions and state transitions for more structured updates.", ["A reducer receives current state and an action, then returns the next state. A discriminated union can describe the allowed action variants.", "This can make complex updates easier to follow because each action is handled in one place. Keep the reducer pure and return new state values."], ["type State = { count: number };", "type Action = { type: 'increment' } | { type: 'reset' };", "function reducer(state: State, action: Action): State { return action.type === 'reset' ? { count: 0 } : { count: state.count + 1 }; }"], ["What should a reducer return?", "How can an action union represent allowed operations?", "Why should a reducer avoid side effects?"]),
  gameTopic("react-ts-context", "Type useContext", "Provide a typed shared value and handle the case where a provider is missing.", ["Context distributes a value through a component tree without passing it through every intermediate component. Give the context a clear value type.", "If no safe default exists, a nullable context plus a checked custom Hook can report a missing provider clearly."], ["type Theme = 'light' | 'dark';", "const ThemeContext = createContext<Theme | null>(null);", "function useTheme() { const theme = useContext(ThemeContext); if (!theme) throw new Error('Theme provider missing'); return theme; }"], ["What does context help share?", "Why can a context default be null?", "What can a checked custom Hook clarify?"]),
  gameTopic("react-ts-usememo", "Type useMemo", "Memoize a calculated value while preserving its inferred type.", ["useMemo caches a calculation result between renders while its dependencies stay the same. TypeScript usually infers the result from the calculation.", "Use it only when caching helps measured performance or preserves a needed reference. It should not be required for correctness."], ["const total = useMemo(() => prices.reduce((sum, price) => sum + price, 0), [prices]);", "const visible = useMemo(() => items.filter(matches), [items, query]);", "// Prefer a plain calculation when it is already inexpensive."], ["What does useMemo return?", "What causes its cached result to be recalculated?", "Should correctness depend on useMemo?"]),
  gameTopic("react-ts-usecallback", "Type useCallback", "Keep a callback's parameter and return types clear when memoizing it.", ["useCallback preserves a function reference while dependencies remain unchanged. The callback's parameter types can often be inferred from its use or declared in a named function type.", "Use it when stable identity matters to a memoized child or dependency list. Do not wrap every function automatically."], ["const handleSave = useCallback(() => save(documentId), [documentId]);", "type SelectHandler = (id: string) => void;", "const onSelect: SelectHandler = id => setSelectedId(id);"], ["What does useCallback preserve between renders?", "When can stable callback identity matter?", "Should every component function be wrapped in useCallback?"]),
  gameTopic("react-ts-useful-types", "Useful React types", "Use React's types to describe nodes, events, and component contracts.", ["React provides types for rendered nodes, event handlers, refs, and component props. Use only the type that matches the contract you need.", "Prefer deriving types from a component or DOM element when appropriate, and avoid overly broad types that accept values the component cannot render."], ["type ContentProps = { children: React.ReactNode };", "type ClickHandler = React.MouseEventHandler<HTMLButtonElement>;", "type InputProps = React.ComponentProps<'input'>;"], ["What can ReactNode describe?", "Which element type parameter can narrow a mouse handler?", "What can ComponentProps<'input'> derive?"]),
  gameTopic("react-ts-dom-events", "Type DOM events", "Type event handlers for the element and event they handle.", ["React event types include the element involved, which helps type properties such as currentTarget.value. Inline handlers often receive contextual typing automatically.", "Use currentTarget when you need the element that owns the handler. Keep event handling separate from data validation."], ["function onChange(event: React.ChangeEvent<HTMLInputElement>) { setQuery(event.currentTarget.value); }", "const onClick: React.MouseEventHandler<HTMLButtonElement> = event => console.log(event.currentTarget.disabled);", "<form onSubmit={(event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); }} />"], ["What does currentTarget refer to?", "Why specify HTMLInputElement for an input change?", "What should form submission often prevent when handled in React?"]),
  gameTopic("react-ts-children", "Type children", "Describe whether a component accepts nested React content.", ["The children prop represents content nested between a component's opening and closing tags. ReactNode is a common type when many kinds of renderable content are accepted.", "If a component requires one specific element or function child, use a narrower type that describes that contract."], ["type PanelProps = { children: React.ReactNode };", "function Panel({ children }: PanelProps) { return <section>{children}</section>; }", "<Panel><p>Nested content</p></Panel>"], ["Where does the children prop come from?", "What can ReactNode represent?", "When might children need a narrower type?"]),
  gameTopic("react-ts-style-props", "Type style props", "Use React's CSS property type for inline style objects.", ["React's CSSProperties type describes supported inline style properties and their value forms. Property names use camelCase in JavaScript objects.", "Use a class or stylesheet for most styling, and reserve inline styles for values that genuinely come from data or runtime state."], ["const style: React.CSSProperties = { backgroundColor: 'lavender', padding: 12 };", "<div style={{ maxWidth: 480, marginInline: 'auto' }} />", "type Tone = 'calm' | 'alert';\nconst colors: Record<Tone, React.CSSProperties> = { calm: { color: 'teal' }, alert: { color: 'crimson' } };"], ["What does CSSProperties describe?", "How are CSS property names written in a JS style object?", "When are inline styles most useful?"]),
  gameTopic("react-ts-further-learning", "Further learning", "Use the concepts to type real components and verify them with project checks.", ["Practice by typing a component's props, then add state, context, and event types only as the feature needs them. Read compiler messages as clues about where the contract is unclear.", "Run the project's type-check and build commands after changes. Remember to validate external data at runtime even when a TypeScript interface describes its expected shape."], ["// Add a precise props type to a reusable component.", "// Model loading and success with a discriminated union.", "// Run npm run typecheck before completing the change."], ["What should guide which React types you add?", "Can an interface validate runtime JSON by itself?", "What commands can verify a project's TypeScript setup?"]),
]);

export const reactCompilerLessons = chapter("Get started", [
  gameTopic("react-compiler-introduction", "React Compiler: Introduction", "Learn how compiler analysis can handle many memoization decisions automatically.", ["React Compiler examines component code and can optimize repeated work and references when it can prove the transformation is safe. This often reduces the need to add memoization helpers by hand.", "The compiler works as part of the build workflow. Clear, predictable components still matter, and compiler optimization does not replace good state design or efficient calculations."], ["// Prefer clear component inputs and state updates.", "// Let compiler analysis handle safe memoization opportunities.", "// Measure real interactions instead of guessing at bottlenecks."], ["What does the compiler analyze?", "Name two manual memoization tools it can reduce the need for.", "Does compiler optimization replace good state design?"]),
  gameTopic("react-compiler-installation", "React Compiler: Installation", "Add compiler support through the build tool or framework used by your project.", ["Compiler installation involves adding compatible tooling and connecting it to the project's compilation pipeline. The exact steps depend on the React version, framework, and build setup.", "Before changing dependencies, check the project versions and use the setup path intended for that environment. Run the normal type-check and build after configuration so problems are caught early."], ["// First inspect package.json and the framework version.", "// Add the compiler integration using the project's supported setup.", "// Run the existing build command to confirm the integration."], ["Why does compiler setup depend on the project?", "What should you inspect before changing compiler dependencies?", "Which check helps confirm that the build integration works?"]),
  gameTopic("react-compiler-adoption", "Incremental Adoption", "Try compiler support on a limited part of a codebase before expanding it.", ["A gradual rollout limits surprises in a large app. Start with a small route or component group, compare behavior, and review compiler diagnostics before widening coverage.", "Keep a clear way to disable or narrow the integration if a specific area is incompatible. Track the rollout with version control so each change is easy to review."], ["// Enable compilation for one app area first.", "// Compare interactions and profiler results before expanding.", "// Record any excluded modules and the reason for each."], ["Why can a gradual rollout help?", "What should be reviewed before widening compiler coverage?", "Why document excluded areas?"]),
  gameTopic("react-compiler-debugging", "Debugging and Troubleshooting", "Separate compiler diagnostics from errors that happen while the app runs.", ["A compiler diagnostic points to code the compiler cannot safely analyze or transform. A runtime error occurs after the application runs, such as reading a missing value or failing to load data.", "Reproduce the issue, read the first useful diagnostic, and narrow the problem to a component or transformation. Compare behavior with compilation disabled only when the project supports that check, then report a small reproducible case to the team."], ["// Check build output for compile-time diagnostics.", "// Check the browser console for runtime exceptions.", "// Reduce the failing view to a small component and its inputs."], ["When does a compiler diagnostic appear?", "Where can a browser runtime exception appear?", "Why reduce an issue to a small reproduction?"]),
  gameTopic("react-compiler-configuration", "Configuration and Reference", "Use configuration and directives only when the project has a clear need.", ["Compiler configuration controls how analysis is applied and can include compatibility choices. Keep settings aligned with the project's React and framework versions.", "Function-level directives may adjust compilation behavior in supported setups. Library authors may need a different build strategy so consumers receive compatible output. Avoid adding options without understanding their effect."], ["// Review compiler configuration alongside framework build settings.", "// Use a function-level opt-in only when the compiler supports it.", "// Test a library build separately from an application build."], ["What should compiler configuration match?", "When might a function-level directive be useful?", "Why can library compilation differ from app compilation?"]),
  gameTopic("react-compiler-resources", "Additional Resources", "Keep compiler knowledge current by checking the project version and team guidance.", ["Compiler behavior can change as tooling evolves. Keep notes about the version in use and revisit setup guidance when upgrading the framework or build system.", "For a team project, record how to enable, inspect, and troubleshoot compiler output. Discuss changes in the project's normal review process."], ["// Record the compiler and framework versions in project notes.", "// Keep a small before-and-after performance reproduction.", "// Review compiler-related changes with the team."], ["Why record compiler and framework versions?", "What makes a performance comparison useful?", "How should compiler setup changes be reviewed?"]),
]);

export const reactCompilerIntroLessons = chapter("React Compiler", [
  gameTopic("react-compiler-what", "What does React Compiler do?", "Understand how build-time analysis can keep component work from repeating unnecessarily.", ["React Compiler analyzes React code during the build and can preserve useful values and functions between renders. This can reduce manual memoization code while keeping components written in ordinary JavaScript.", "The compiler follows React's rules about render purity and state. It does not make slow algorithms fast automatically; it helps avoid work that does not need to run again."], ["function Price({ amount }) { return <strong>{formatPrice(amount)}</strong>; }", "// Compiler analysis may reuse a calculation when its inputs have not changed.", "// Keep rendering pure: compute output from props and state."], ["At what stage does React Compiler analyze components?", "What kind of repeated work can it help avoid?", "Does it replace the need for efficient algorithms?"]),
  gameTopic("react-compiler-before", "Before React Compiler", "See why hand-written memoization can become difficult to maintain.", ["Before compiler optimization, developers sometimes use memo, useMemo, or useCallback to skip work after measuring a performance issue. These tools add dependency lists and reference-stability concerns.", "A newly created inline callback can still change identity each render, even if a nearby function is memoized. Optimize only when needed and check which prop actually changes."], ["const total = useMemo(() => sum(values), [values]);", "const onSave = useCallback(() => save(id), [id]);", "<Row onSelect={() => onSelect(item.id)} /> // new inline callback each render"], ["What does useMemo cache?", "Why can an inline callback change identity?", "Why should manual memoization be based on evidence?"]),
  gameTopic("react-compiler-after", "After React Compiler", "Write straightforward components while the compiler handles safe reuse opportunities.", ["With compiler support, code can focus on the calculation and event behavior rather than adding memoization everywhere. The compiler may preserve appropriate values and callbacks when inputs are unchanged.", "Keep components pure and follow Hook rules so analysis can understand their behavior. Review build diagnostics and test interactions after enabling the compiler."], ["const total = sum(values);", "const onSave = () => save(id);", "<Row onSelect={() => onSelect(item.id)} />"], ["What can compiler support reduce in component code?", "What coding rules help analysis understand a component?", "What should you do after enabling compilation?"]),
  gameTopic("react-compiler-try", "Should I try the compiler?", "Decide whether to test compiler support in the context of your project.", ["Compiler optimization is optional in many setups. A small trial can show whether it works with the app's patterns and build tooling.", "Start with a development branch and a representative feature. Compare behavior and performance, then expand only when the team understands the results."], ["// Choose one representative component group.", "// Record a baseline interaction before enabling the compiler.", "// Compare the same interaction after enabling it."], ["What is a sensible first step when trying the compiler?", "Why record a baseline?", "What should guide a wider rollout?"]),
  gameTopic("react-compiler-safety", "Is it safe to use?", "Understand that compiler safety depends on React rules and project behavior.", ["Compiler transformations rely on predictable component behavior. Mutating props, state, or external values during render can break assumptions and should be corrected regardless of compiler use.", "Test important interactions and inspect diagnostics. If behavior changes, isolate the component and check for violations of React's rules before blaming the optimizer."], ["// Avoid mutating props: create a derived value instead.", "// Keep side effects in event handlers or appropriate Effects.", "// Test state changes and navigation after a build change."], ["What kind of code can make compiler assumptions unsafe?", "Where should side effects generally happen?", "What should you test after compiler changes?"]),
  gameTopic("react-compiler-tooling", "What build tools are supported?", "Check how compiler integration fits the project's existing build system.", ["Compiler integration can be provided through different build pipelines. The available route depends on the framework, bundler, and installed versions.", "Avoid adding a second transform pipeline without a reason. Check the project's supported integration and confirm that the production build uses the same intended configuration."], ["// Inspect the framework and bundler already in use.", "// Use one supported compiler integration path.", "// Verify both local development and production builds."], ["What project details affect the integration choice?", "Why avoid duplicate transforms?", "Which two environments should you verify?"]),
  gameTopic("react-compiler-memo", "What about useMemo, useCallback, and memo?", "Treat manual memoization as a deliberate choice when compiler support is present.", ["Compiler support may remove the need for many manual memoization wrappers, but existing code can keep them during a gradual transition. Understand why a wrapper exists before removing it.", "Manual memoization can still be useful in special cases or where a library contract expects stable references. Measure and follow the compiler and framework guidance for that version."], ["// Keep an existing memo temporarily while validating rollout.", "// Remove a wrapper only after confirming behavior and performance.", "// Check whether a consumer relies on stable object identity."], ["Should every existing memo wrapper be deleted at once?", "Why might a library still need a stable reference?", "What evidence helps decide whether a wrapper is needed?"]),
  gameTopic("react-compiler-try-it", "Try React Compiler", "Use a small experiment to see compiler output and behavior for yourself.", ["Pick a component with repeated rendering work, capture a baseline, and enable compiler support using the project's supported setup. Keep the change isolated so results are easy to compare.", "Use the Profiler or build diagnostics to inspect what changed. Focus on user-visible behavior and measured work rather than expecting every component to render fewer times."], ["// Select a small component with stable sample data.", "// Record render behavior before and after.", "// Revert the experiment cleanly if it causes issues."], ["Why choose a small experiment?", "Which tool can help compare render behavior?", "Does compiler use guarantee fewer renders for every component?"]),
  gameTopic("react-compiler-more", "Additional resources", "Keep notes on compiler versions and the setup used by your app.", ["Compiler behavior and integrations can evolve. Record the framework, compiler, and build tool versions used in a successful setup.", "For questions, use the project's official documentation and team review process. Share a minimal reproduction when reporting an issue."], ["// Note the framework and compiler versions.", "// Save the successful build configuration with the project.", "// Create a minimal reproduction for a suspected compiler issue."], ["Why record versions?", "What should be saved with project setup notes?", "Why create a minimal reproduction for an issue?"]),
]);

export const reactCompilerInstallLessons = chapter("React Compiler", [
  gameTopic("react-compiler-install-guide", "React Compiler: Installation", "Prepare a project and connect compiler support to its build pipeline.", ["Compiler setup starts with checking the React version, build tool, and existing transforms. The compiler is added as a development dependency because it runs while source code is built.", "The integration differs across Babel-based tools, frameworks, and native app bundlers. Follow the setup intended for the exact tool versions in the project and make sure compiler analysis runs before other source transforms that could hide useful structure."], ["npm install --save-dev babel-plugin-react-compiler", "// Check React, bundler, and plugin versions before setup.", "// Add the compiler to the build pipeline used by the app."], ["Why inspect project versions before installing?", "Why is the compiler usually a development dependency?", "When should compiler analysis run in a transform pipeline?"]),
  gameTopic("react-compiler-prerequisites", "Prerequisites", "Confirm the React version and build setup can support the compiler integration.", ["React Compiler works best with a compatible React version and a supported build integration. Older projects may need compatibility settings or a different rollout plan.", "Check the app's framework and bundler before copying configuration examples. If the project is managed by a framework, prefer its supported configuration rather than adding a separate Babel path blindly."], ["// Inspect package.json for React and framework versions.", "// Identify whether the app uses Babel, Vite, Next.js, or another pipeline.", "// Confirm the compiler integration supports those versions."], ["What should be checked before setup?", "Why can framework-managed apps need a different path?", "What is a risk of adding another transform pipeline blindly?"]),
  gameTopic("react-compiler-install-package", "Install the compiler package", "Add the compiler integration package to development dependencies.", ["A compiler plugin is part of the build toolchain, not code that users import into a component. Add it as a development dependency with the package manager used by the project.", "Use one package manager consistently so the lockfile remains in sync. Review the package's supported version range before updating a mature app."], ["npm install --save-dev babel-plugin-react-compiler", "yarn add --dev babel-plugin-react-compiler", "pnpm add --save-dev babel-plugin-react-compiler"], ["Why is the plugin not imported into a React component?", "Why keep the package manager consistent?", "What should you review before updating compiler versions?"]),
  gameTopic("react-compiler-basic-setup", "Basic Setup", "Add compiler support with minimal configuration before tuning special cases.", ["Many projects need only a small build configuration change. Start with the default integration supported by the current framework and compiler versions.", "Avoid adding extra options unless the project has a clear compatibility need. Save the configuration with the app and verify the actual production build."], ["// Begin with the framework's documented default integration.", "// Keep special compatibility options out until needed.", "// Run the production build after editing configuration."], ["Why start with minimal configuration?", "When should special compiler options be added?", "Which build should be checked after configuration changes?"]),
  gameTopic("react-compiler-babel", "Configure Babel", "Place the compiler plugin early in a Babel-based transform pipeline.", ["Babel integrations connect the compiler to source transformation. The compiler should analyze the original component code before transforms that rewrite it.", "If a framework already configures Babel, extend that configuration in the supported way and avoid replacing existing presets accidentally."], ["// babel.config.js\nmodule.exports = { plugins: ['babel-plugin-react-compiler'] };", "// Keep compiler analysis before other source-rewriting plugins.", "// Preserve existing presets required for JSX and the framework."], ["What does Babel do in this setup?", "Why should compiler analysis happen early?", "What can happen if existing presets are removed accidentally?"]),
  gameTopic("react-compiler-vite", "Configure Vite", "Connect the compiler through the Vite React integration supported by your plugin versions.", ["Vite React integrations can expose compiler support through a preset or a Babel plugin hook. The exact option changes across plugin versions, so match examples to the installed release.", "Keep Vite plugin ordering and transforms consistent with the project. After setup, verify both hot development updates and a production build."], ["// Inspect installed @vitejs/plugin-react version.", "// Add the compatible compiler preset or Babel integration.", "// Run the Vite dev server and production build to verify."], ["Why does Vite setup depend on plugin version?", "What should be verified in addition to the dev server?", "Why preserve existing Vite plugins?"]),
  gameTopic("react-compiler-nextjs", "Configure Next.js", "Use the compiler integration supported by the installed Next.js release.", ["Next.js compiler support is tied to specific framework versions and configuration. Check the installed version's local docs and config types before enabling it.", "Avoid adding a manual Babel setup unless the framework's documented integration calls for it. Run type-checking and a production build to catch configuration issues."], ["// Check the installed Next.js version and local configuration docs.", "// Enable compiler support using that release's supported option.", "npm run build"], ["Why check the installed Next.js version first?", "Why avoid a second Babel pipeline without guidance?", "Which command can confirm production compilation?"]),
  gameTopic("react-compiler-router", "Configure React Router", "Integrate compiler transforms with the Vite-based router build carefully.", ["A React Router project may use Vite for its build. Add compiler support through the project's compatible Vite/Babel integration while preserving router plugins.", "If TypeScript or other transforms are involved, verify their order and supported settings. Keep route loading and compilation diagnostics separate when troubleshooting."], ["// Inspect the generated Vite configuration.", "// Add the compatible Babel integration without removing router setup.", "// Build and visit a route directly to verify output."], ["What build tool may power a React Router project?", "Why preserve the router plugin?", "What route behavior should be checked after a build change?"]),
  gameTopic("react-compiler-webpack", "Configure Webpack", "Add compiler support to a Webpack pipeline without disrupting existing loaders.", ["Webpack projects may use Babel loader to transform React source. Connect the compiler where JSX and JavaScript are transformed, and preserve loader rules the app relies on.", "Test representative file types and production output. Avoid running the same compiler transform twice through overlapping rules."], ["// Locate the Babel loader rule for application source.", "// Add the compiler plugin to the appropriate Babel config.", "// Verify TSX/JSX files are transformed once."], ["Where might a Webpack app connect the compiler?", "Why preserve existing loader rules?", "What is a problem with duplicate transforms?"]),
  gameTopic("react-compiler-expo", "Configure Expo", "Use the Expo integration that matches its managed build setup and version.", ["Expo projects have their own Metro and Babel configuration conventions. Check the installed Expo SDK and supported compiler setup before changing them.", "Keep native platform transforms intact and test on the target device or simulator. A web-only check does not confirm that a native bundle works."], ["// Check Expo SDK and existing Babel configuration.", "// Add compiler support through the compatible Expo setup.", "// Create and run a native development build for verification."], ["Why check the Expo SDK before changing config?", "What native behavior should be preserved?", "Why is a web build alone insufficient for a native app?"]),
  gameTopic("react-compiler-metro", "Configure Metro for React Native", "Add compiler support within the Metro/Babel pipeline used by a native app.", ["Metro bundles React Native code and commonly works with Babel transforms. Compiler configuration must fit the app's Metro and Babel setup.", "Test the bundle on the platforms the app supports. Keep platform-specific transforms and development tooling intact."], ["// Inspect metro.config.js and babel.config.js.", "// Add the compiler plugin in the supported transform order.", "// Build or run Android and iOS targets used by the project."], ["What does Metro bundle?", "Which existing config files may affect the integration?", "Why test platform builds after setup?"]),
  gameTopic("react-compiler-rspack", "Configure Rspack", "Check the project's React transform path before adding compiler support.", ["Rspack setups can use different React and Babel integrations. Identify which loader or plugin processes JSX before choosing where the compiler belongs.", "Keep the configuration aligned with the tool versions and confirm the compiler runs once on the intended application files."], ["// Inspect Rspack module rules for JSX/TSX.", "// Add the compiler through the supported transform integration.", "// Confirm a production bundle completes successfully."], ["What determines where the compiler belongs in Rspack?", "Why should it run only once on app source?", "What does a successful bundle verify?"]),
  gameTopic("react-compiler-rsbuild", "Configure Rsbuild", "Enable the compiler through Rsbuild's supported React integration.", ["Rsbuild provides React-oriented project configuration, but compiler support still depends on installed versions and the transform path. Use the integration documented for that project setup.", "Keep the generated defaults and add only the compiler-specific change. Confirm both local development and production output."], ["// Inspect the Rsbuild React plugin and project version.", "// Add compiler support using the supported integration point.", "// Run the app and create a production build."], ["Why use the supported Rsbuild integration?", "What should remain intact when editing generated config?", "Which two build modes should be checked?"]),
  gameTopic("react-compiler-eslint", "ESLint Integration", "Use lint rules to catch React patterns that can block safe optimization.", ["Lint integration can surface violations of React's rules and compiler diagnostics during development. These checks help identify patterns that should be fixed or left uncompiled.", "Keep lint versions and plugin configuration compatible. Treat warnings as information to investigate, not as a reason to disable all checks."], ["// Run the project's lint script after enabling compiler support.", "// Review diagnostics for the specific component and rule.", "// Fix a rule violation before suppressing it."], ["What can compiler-aware lint checks report?", "Why inspect a diagnostic rather than disabling the rule globally?", "What should be considered before suppressing one warning?"]),
  gameTopic("react-compiler-verify", "Verify Your Setup", "Confirm compiler integration through development tools and build output.", ["A successful setup should build the app and show that intended files are processed. Check the browser behavior too; compilation success alone does not prove every feature works.", "Use one representative component and compare diagnostics or profiling information. Keep the verification steps repeatable for future upgrades."], ["// Run the project's type-check and lint scripts.", "// Start the development server and exercise a key interaction.", "// Run the production build and review its output."], ["What does a successful build verify?", "Why test an interaction in the browser?", "Why document verification steps?"]),
  gameTopic("react-compiler-check-devtools", "Check React Developer Tools", "Use component inspection and profiling to examine runtime behavior after setup.", ["Developer Tools can show component structure and runtime values. The Profiler can help compare rendering work before and after a compiler change.", "A changed render count is not automatically a bug or improvement. Check that the UI remains correct and measure user-facing performance."], ["// Inspect props and state for the test component.", "// Record the same interaction before and after the change.", "// Compare timings and UI behavior, not just render counts."], ["What can component inspection confirm?", "What can the Profiler help compare?", "Why is render count alone not enough?"]),
  gameTopic("react-compiler-check-output", "Check Build Output", "Read build logs and generated diagnostics to confirm the integration is active.", ["Build output may report compiler diagnostics or files that were skipped. Review these messages to understand what was analyzed and where the compiler could not operate.", "Do not assume a quiet build means every component was compiled. Check the integration's diagnostics and test a known component."], ["// Save and inspect the full production build log.", "// Look for compiler diagnostics or skip reasons.", "// Confirm a known component is included in the transform."], ["What might build diagnostics explain?", "Does a quiet log prove every component was compiled?", "Why check a known component?"]),
  gameTopic("react-compiler-troubleshoot", "Troubleshooting", "Narrow setup or behavior problems to a tool version, transform, or component.", ["If the build fails, inspect the first compiler or bundler error and verify package versions and plugin order. If the app builds but behaves differently, isolate the component and check for React rule violations.", "Make one configuration change at a time and rerun the same check. This helps identify which change caused the issue."], ["// Capture the first meaningful error and relevant versions.", "// Temporarily test a small component to narrow the source.", "// Change one setting, rebuild, and compare."], ["What should you inspect first when a build fails?", "How can you narrow a runtime behavior issue?", "Why make one config change at a time?"]),
  gameTopic("react-compiler-opt-out", "Opt out specific components", "Limit compilation for a component only when a confirmed issue requires it.", ["Some code may not be understood by the compiler or may need special treatment. Follow the compiler's supported opt-out mechanism for the installed version and keep the exclusion as narrow as possible.", "Document the reason and revisit it after fixing the underlying pattern or upgrading tooling. Broad opt-outs can hide useful coverage."], ["// Identify the exact component with a reproducible issue.", "// Use only the supported opt-out method for the installed compiler.", "// Record why the component is excluded and when to review it."], ["When is a narrow opt-out useful?", "Why keep exclusions small?", "What information should accompany an exclusion?"]),
  gameTopic("react-compiler-install-next", "Next Steps", "Maintain compiler support as the project and build tools change.", ["After verification, keep compiler setup documented and include relevant checks in the normal workflow. Revisit compatibility when upgrading React, the framework, or bundler.", "Expand adoption gradually and remove temporary workarounds only after checking behavior and performance."], ["// Add compiler verification to the project's build checklist.", "// Recheck integration after a framework upgrade.", "// Review old exclusions during maintenance."], ["What upgrades can affect compiler integration?", "Why keep verification in the project workflow?", "When should temporary workarounds be removed?"]),
]);

export const reactCompilerAdoptionLessons = chapter("React Compiler", [
  gameTopic("react-compiler-incremental", "Incremental Adoption", "Roll out compiler support in small, reviewable parts of an existing app.", ["Incremental adoption means enabling compilation for a limited area first, checking behavior, and expanding when the team is confident. It helps keep the change manageable in a large project.", "Track what is enabled, what remains excluded, and which checks were run. Use a measured rollout to find code patterns that need attention before the compiler reaches more users."], ["// Start with a small, well-tested feature directory.", "// Compare behavior and performance before expanding.", "// Record enabled areas and known exclusions."], ["Why begin with a limited part of a codebase?", "What should be reviewed before expanding coverage?", "Why track exclusions and rollout progress?"]),
  gameTopic("react-compiler-why-adopt", "Why Incremental Adoption?", "Build confidence while addressing codebase-specific issues gradually.", ["A compiler rollout can expose patterns that do not follow React's rules. Starting small lets a team fix those patterns step by step and check that important interactions still work.", "Production apps also benefit from controlled comparisons. Collect evidence about correctness and user-facing performance rather than assuming every optimization improves the experience."], ["// Run existing tests on the first enabled feature.", "// Compare a key interaction before and after compilation.", "// Fix a Rules of React warning before expanding rollout."], ["How does a small rollout help with existing code issues?", "What should performance comparisons focus on?", "Why are existing behavior checks important?"]),
  gameTopic("react-compiler-adoption-approaches", "Approaches to Incremental Adoption", "Choose a rollout method that fits the project's build setup and desired control.", ["Teams can scope compilation by source directory, explicitly opt in selected functions, or use a runtime gate when the integration supports it. Each method has different setup and maintenance costs.", "Choose the simplest approach that provides enough control. Confirm the behavior supported by the installed compiler version before relying on configuration options."], ["// Directory scope: compile a selected feature folder.", "// Annotation scope: mark selected functions in a supported mode.", "// Runtime gate: enable for a controlled test group when supported."], ["Name one way to limit compiler coverage.", "What should you confirm before using a configuration option?", "Why choose the simplest adequate rollout method?"]),
  gameTopic("react-compiler-directory", "Directory-Based Adoption", "Apply compiler support to selected source folders through build configuration.", ["Some build systems let a transform apply only to matching files or folders. This can provide a clear boundary between newly adopted code and legacy areas.", "Keep file matching explicit and test that both intended and excluded folders behave as expected. Add new directories only after reviewing their code and build output."], ["// Scope the compiler transform to src/features/new-ui.", "// Keep src/legacy outside the initial match.", "// Add another folder after checks pass for the first one."], ["What does directory scoping control?", "Why test excluded folders too?", "When should another directory be added?"]),
  gameTopic("react-compiler-babel-overrides", "Babel Overrides", "Use per-file configuration only when Babel is the active supported transform path.", ["Babel overrides can apply a plugin to matching files while leaving other files under different rules. This makes folder-by-folder adoption possible in a Babel pipeline.", "Frameworks may manage Babel configuration internally, and override syntax can depend on the setup. Check how the framework merges configuration before adding patterns."], ["// Example concept: apply compiler plugin to src/modern/**.", "// Keep unrelated global plugins in their existing configuration.", "// Verify the match against a real component file."], ["What can a Babel override target?", "Why might a framework change how overrides are applied?", "How can you verify a file pattern matches the intended component?"]),
  gameTopic("react-compiler-basic-adoption-config", "Basic Configuration", "Enable one small source area and keep the rest of the setup unchanged.", ["Begin with a narrow match and the default compiler behavior supported by the installed toolchain. Avoid creating complex per-folder options before the basic path is verified.", "Keep configuration readable so other developers understand which code is compiled and why."], ["// First scope: src/features/search/**", "// Leave unrelated global transforms as they are.", "// Add a short comment explaining the rollout boundary."], ["Why begin with default compiler behavior?", "What should configuration communicate to teammates?", "Why avoid adding many options at the start?"]),
  gameTopic("react-compiler-expand-coverage", "Expanding Coverage", "Grow the enabled area after a small rollout has passed its checks.", ["Coverage can expand by adding reviewed folders or components. Make each expansion a separate change so regressions can be traced to a specific boundary.", "Include tests, key manual interactions, and build diagnostics in the decision. A folder name alone does not prove its components follow React rules."], ["// Expand from one feature folder to a second.", "// Keep the change isolated in version control.", "// Re-run tests and inspect diagnostics after each expansion."], ["What makes an expansion easy to review?", "What evidence should be gathered before expansion?", "Does a folder name guarantee safe compilation?"]),
  gameTopic("react-compiler-options-adoption", "Adopt with Compiler Options", "Use scoped options only for a specific compatibility need.", ["Some setups allow different compiler settings for different files. This can help when parts of an app have distinct requirements, but creates more configuration to maintain.", "Document why settings differ and confirm the values are supported by the installed compiler. Keep the default path for areas that do not need special treatment."], ["// Apply a special option only to a named experimental folder.", "// Keep stable app folders on the standard configuration.", "// Record which issue the per-folder setting addresses."], ["When can per-folder compiler options help?", "Why document different settings?", "What should be checked before using an option?"]),
  gameTopic("react-compiler-opt-in-memo", "Opt-In Mode with use memo", "Compile selected components or Hooks using an explicit opt-in when supported.", ["An annotation mode can require a directive in each function that should be compiled. This gives fine-grained control but adds a reminder to maintain when new components are created.", "Use opt-in mode when component-level boundaries are more useful than directory boundaries. Keep the directive only where the configured compiler recognizes it."], ["function Results({ items }) { 'use memo'; return <List items={items} />; }", "function useSortedItems(items) { 'use memo'; return [...items].sort(compare); }", "// Add the opt-in to new functions that belong in this mode."], ["What does an explicit opt-in directive identify?", "What is a maintenance cost of opt-in mode?", "Why check that the configured compiler recognizes the directive?"]),
  gameTopic("react-compiler-annotation-config", "Annotation Mode Configuration", "Configure the compiler for explicit function-level adoption when the toolchain supports it.", ["Annotation mode changes the compiler's selection behavior: only functions marked with the recognized opt-in are compiled. The configuration belongs in the build integration, not inside arbitrary application settings.", "Check the installed compiler reference for the exact option name and behavior. Then verify one marked and one unmarked component."], ["// Concept: set the supported compilation mode to annotation.", "// Mark one test component with the documented directive.", "// Confirm an unmarked component remains outside the rollout."], ["What changes in annotation mode?", "Where does this mode belong?", "How can you test that selection behavior is correct?"]),
  gameTopic("react-compiler-directive", "Using the Directive", "Place an opt-in or opt-out directive where the compiler expects it.", ["Directives are special string expressions placed at the start of a function body. They can affect how a supported compiler handles that function.", "Use only directives supported by the installed version and configuration. Keep them close to the function they affect and explain unusual usage in a comment."], ["function ChartPanel() { 'use memo'; return <Chart />; }", "function LegacyPanel() { 'use no memo'; return <OldChart />; }", "// Check exact directive support before using it in project code."], ["Where is a function-level directive placed?", "What should you verify before using a directive?", "Why keep a directive close to the function it affects?"]),
  gameTopic("react-compiler-runtime-gating", "Runtime Feature Flags with Gating", "Use a runtime gate for a controlled compiler rollout when the integration supports it.", ["A runtime gate can select compiled or original behavior based on a feature flag. This can support staged exposure or controlled comparisons, but requires careful testing and a supported compiler integration.", "Keep the flag decision centralized and stable for a session. Track both behavior and errors so the rollout can be adjusted responsibly."], ["// Ask a central feature-flag service whether the rollout is enabled.", "// Use a consistent gate result for the current app session.", "// Compare error and performance signals across enabled groups."], ["What does runtime gating control?", "Why should the gate result be consistent?", "What signals should be observed during a gated rollout?"]),
  gameTopic("react-compiler-how-gating", "How Gating Works", "Understand that a gate selects a compiled path or the regular path at runtime.", ["In a supported setup, generated code can check a gate before choosing optimized behavior. If the gate is off, the regular implementation remains available.", "The precise generated behavior depends on compiler integration. Do not assume a gate exists just because a feature flag is present; verify the transformed output and test both paths."], ["// Gate enabled: exercise the compiler-generated path.", "// Gate disabled: exercise the regular path.", "// Add a test that runs each state of the gate."], ["What does the runtime gate choose between?", "Why test both gate outcomes?", "Does any feature flag automatically enable compiler gating?"]),
  gameTopic("react-compiler-gating-config", "Gating Configuration", "Connect a compiler gate to a named project feature-flag function.", ["Gating configuration tells the transform where to find a function that returns whether the optimized path is enabled. The shape and option names depend on compiler version.", "Keep the gate function small and testable. Avoid importing unrelated application state into compiler configuration."], ["// Define a small isCompilerEnabled() gate function.", "// Connect the compiler configuration to that function.", "// Unit-test enabled and disabled results."], ["What does gating configuration point to?", "Why keep the gate function small?", "Which two return states should be tested?"]),
  gameTopic("react-compiler-feature-flag", "Implementing the Feature Flag", "Connect rollout decisions to a controlled and observable flag.", ["A feature flag can be based on a safe rollout rule such as a development-only setting or a managed experiment group. The flag should be easy to turn off if problems appear.", "Protect the flag service from affecting app startup, define a fallback behavior, and avoid placing private credentials in client-side code."], ["function isCompilerEnabled() { return rolloutConfig.compilerEnabled === true; }", "// Use a safe default when remote flag data is unavailable.", "// Log rollout status without exposing private configuration."], ["What is a safe purpose for a feature flag here?", "What should happen if remote flag data is unavailable?", "Why should private credentials stay out of client code?"]),
  gameTopic("react-compiler-adoption-troubleshoot", "Troubleshooting Adoption", "Use diagnostics, small rollbacks, and React rule checks to resolve rollout issues.", ["If a component behaves unexpectedly, reproduce it, inspect compiler and lint diagnostics, and reduce the case to its smallest component. Check for mutation or other violations of React's rules.", "A narrowly scoped exclusion can help while investigating if the compiler supports it. Record the reason and remove the exclusion after the underlying issue is fixed."], ["// Reproduce with a small input and one interaction.", "// Check lint and build diagnostics for the component.", "// Temporarily narrow coverage, then retest after a fix."], ["What should you do before changing rollout configuration?", "What patterns should be checked in a suspicious component?", "Why should temporary exclusions be reviewed later?"]),
  gameTopic("react-compiler-adoption-next", "Next Steps", "Use the rollout results to decide whether to expand, pause, or adjust coverage.", ["Summarize which areas are enabled, what checks passed, and what issues remain. Share the result with the team before making a broad change.", "Continue in small steps and revisit the plan when React, framework, or compiler versions change. Remove obsolete opt-outs and flags during maintenance."], ["// Record coverage and verification results.", "// Expand one reviewed area at a time.", "// Recheck the integration after dependency upgrades."], ["What should an adoption summary include?", "Why expand one area at a time?", "When should rollout configuration be reviewed again?"]),
]);

export const reactCompilerDebugLessons = chapter("React Compiler", [
  gameTopic("react-compiler-debugging", "Debugging and Troubleshooting", "Separate build-time compiler errors from unexpected behavior while the app runs.", ["Compiler diagnostics appear while source is transformed or built. Runtime issues appear after the app starts, such as a view showing stale information or an Effect running unexpectedly.", "The compiler aims to skip code it cannot safely analyze, so a runtime issue should be investigated alongside the Rules of React. Reproduce it in a small case and compare behavior with compilation disabled only through a supported diagnostic method."], ["// Build error: inspect terminal output and file/line details.", "// Runtime issue: reproduce one interaction in the browser.", "// Compare the same component with a supported compiler opt-out."], ["When does a compiler diagnostic appear?", "When does a runtime issue appear?", "Why reproduce an issue with one small interaction?"]),
  gameTopic("react-compiler-behavior", "Understanding Compiler Behavior", "Learn why React rules help the compiler optimize code safely.", ["The compiler relies on predictable render behavior: components should produce UI from props and state without mutating values or causing side effects during render.", "If analysis cannot establish that a transformation is safe, it may leave that code unchanged. A skipped component is not necessarily broken; it may simply use a pattern the compiler cannot verify."], ["// Derive a new value instead of mutating a prop.", "// Keep render output deterministic for the same inputs.", "// Read build diagnostics to see when code is skipped."], ["What behavior does the compiler expect from rendering?", "What may happen when safe analysis is uncertain?", "Does a skipped component necessarily indicate an error?"]),
  gameTopic("react-compiler-error-types", "Compiler Errors vs Runtime Issues", "Use the time and place of a failure to choose a debugging path.", ["A compiler or bundler error stops the build and usually includes a diagnostic in terminal output. Check the first meaningful error, source location, and package versions.", "A runtime issue happens after the build succeeds. Inspect the browser console, the affected component's inputs, state changes, and the interaction that triggers the behavior."], ["// Build failure: note the transform and source location.", "// Runtime failure: capture the console message and reproduction steps.", "// Record React, compiler, and framework versions."], ["Where do build-time errors usually appear?", "What tools help investigate runtime behavior?", "Which version details are useful when reporting?"]),
  gameTopic("react-compiler-breaking-patterns", "Common Breaking Patterns", "Look for code that relies on object identity or memoization for correctness.", ["Memoization is intended as a performance optimization, not a guarantee that a value remains stable forever. Code that relies on a cached object or function to make an Effect correct can behave unexpectedly when identity changes.", "Review Effects, dependency lists, and reference comparisons. Prefer deriving values during render, using stable identifiers, and modeling the actual state transition rather than depending on an optimization side effect."], ["// Risky: Effect behavior depends on an object recreated every render.", "// Safer: depend on primitive inputs such as userId.", "// Avoid using memoization as the only protection against repeated state updates."], ["What is memoization primarily intended to improve?", "Why can recreated object references affect Effects?", "What is safer than relying on a cache for correctness?"]),
  gameTopic("react-compiler-workflow", "Debugging Workflow", "Use a repeatable process to isolate compiler-related behavior changes.", ["First reproduce the problem and record the expected and actual behavior. Identify whether it occurs during build or after the app starts.", "For runtime issues, narrow the affected component and verify React rules. Change one factor at a time, run the same interaction, and remove temporary diagnostics after the fix."], ["// 1. Reproduce and record the steps.", "// 2. Narrow to one component and inspect lint/build output.", "// 3. Change one cause, then rerun the same check."], ["What should be recorded before changing code?", "Why narrow the issue to one component?", "Why change one factor at a time?"]),
  gameTopic("react-compiler-build-errors", "Compiler Build Errors", "Investigate a build that fails while the compiler processes source code.", ["Read the earliest relevant diagnostic and confirm which transform produced it. Check whether a config change, unsupported syntax, or version mismatch explains the failure.", "If the error appears to come from the compiler itself, create a minimal case and collect exact versions before reporting. Keep the full terminal context needed to reproduce it."], ["// Capture the first compiler error and its source location.", "// Check package versions and plugin ordering.", "// Reduce the code while preserving the same build failure."], ["What should you read first in a long build log?", "Name two configuration details to check.", "Why make a minimal build reproduction?"]),
  gameTopic("react-compiler-runtime-issues", "Runtime Issues", "Trace unexpected UI behavior to inputs, state, Effects, or unsupported assumptions.", ["When a page behaves differently after compilation, reproduce the exact action and inspect state and props around the affected component. Check for mutation, render side effects, and logic that depends on referential equality.", "A compiler opt-out can help test whether compilation is involved, if the installed integration supports it. It is a diagnostic step, not a final fix; correct the underlying code pattern and retest."], ["// Check whether a prop object changes identity on each render.", "// Inspect Effect dependencies and state updates.", "// Temporarily compare with a supported per-component opt-out."], ["What should be inspected around the affected component?", "Why is an opt-out only a diagnostic step?", "What patterns can cause unexpected repeated Effects?"]),
  gameTopic("react-compiler-temporary-opt-out", "Temporarily Disable Compilation", "Isolate one component to compare compiled and regular behavior.", ["Some compiler versions support a function-level opt-out directive. Use it only for a short test on the smallest affected component and confirm that the build recognizes it.", "If the issue disappears, investigate assumptions in that component rather than leaving the opt-out indefinitely. If it remains, look for a regular application bug unrelated to compilation."], ["function ResultsPanel() { 'use no memo'; return <Results />; }", "// Test the same inputs and actions with and without the opt-out.", "// Remove the temporary directive after diagnosis."], ["What does a temporary opt-out help compare?", "What should happen if the issue remains with compilation disabled?", "Why remove the opt-out after diagnosis?"]),
  gameTopic("react-compiler-stepwise-fix", "Fix Issues Step by Step", "Correct the underlying pattern and verify each change independently.", ["Identify the code assumption behind the issue, such as mutation or relying on a memoized reference for correctness. Make the smallest correction that restores the React rules.", "Run the same test after each fix, remove temporary opt-outs, and check the component again with compiler support enabled."], ["// Replace in-place mutation with a copied array.", "// Depend on a stable primitive ID rather than a freshly created object.", "// Re-enable compilation and repeat the reproduction steps."], ["What should a final fix address?", "Why test after each small change?", "What should be done with temporary diagnostic directives?"]),
  gameTopic("react-compiler-report-bugs", "Reporting Compiler Bugs", "Prepare a small, useful report when evidence points to a compiler issue.", ["Before reporting, check React rules and confirm that the issue happens only with compiler support enabled. Reduce the app to the smallest example that still shows the difference.", "Include expected and actual behavior, exact React and compiler versions, build setup, and relevant diagnostic output. Do not include private user data or credentials in a reproduction."], ["// Provide a minimal component and its test inputs.", "// Record exact framework and compiler versions.", "// Explain how to reproduce and what result was expected."], ["What must a good bug report include?", "Why confirm behavior without compiler support?", "Why keep private data out of a reproduction?"]),
  gameTopic("react-compiler-debug-next", "Next Steps", "Prevent future issues with React rules, tests, and a gradual rollout.", ["Learning React's rules and keeping lint checks enabled can catch many risky patterns early. A gradual compiler rollout gives time to resolve issues while keeping changes reviewable.", "After fixing an issue, keep a regression test for important behavior and revisit temporary exclusions during upgrades."], ["// Keep Hooks and render-purity lint checks enabled.", "// Add a test for the interaction that exposed the problem.", "// Review compiler exclusions after dependency updates."], ["What can lint checks catch early?", "Why add a regression test?", "When should temporary exclusions be revisited?"]),
]);

const uiTopic = (id: string, title: string, summary: string, content: string[], examples: [string, string, string], quizData: [[string, string, string, number, string], [string, string, string, number, string], [string, string, string, number, string]]) => ({
  id, title, summary, content, level: "Beginner" as const,
  examples: examples.map((code, i) => ({ title: `Example ${i + 1}`, code, result: "Use this pattern in a small component and observe the rendered UI." })),
  quizzes: quizData.map(([question, a, b, answer, explanation]) => ({ question, options: [a, b, "It is unrelated to the concept"], answer, explanation })),
});

export const describingUiLessons = chapter("Learn React · Describing the UI", [
  uiTopic("react-describing-ui", "Describing the UI", "Break an interface into components, then describe how each component should appear.", ["React builds interfaces from components: reusable pieces that combine markup with display logic. Start by identifying the parts of a screen and the data each part needs.", "Components receive inputs and return UI. You can compose small parts into larger page structures, then use props and JavaScript expressions to show the right content."], ["function PageTitle() { return <h1>Reading list</h1>; }", "function Notice() { return <p>Your changes are saved.</p>; }", "function Screen() { return <main><PageTitle /><Notice /></main>; }"], [["What is a React component?", "A reusable function that describes UI", "A CSS file", 0, "Components describe reusable parts of the interface."], ["How can a page combine smaller components?", "By nesting them in a parent component", "By placing all code in one string", 0, "A parent can render child components to compose a page."], ["What is a useful first step when planning a screen?", "Identify its parts and the data they need", "Add state to every element", 0, "A clear breakdown helps shape component responsibilities."]] ),
  uiTopic("react-first-component", "Your First Component", "Write a function component and render it from another component.", ["A function component returns React UI, usually written with JSX. Use a capitalized name for custom components so JSX recognizes them as components.", "Keep a component focused on a clear piece of the interface. A small component can be reused in several places with different props."], ["function Welcome() { return <h1>Welcome</h1>; }", "function SaveButton() { return <button>Save</button>; }", "function Page() { return <section><Welcome /><SaveButton /></section>; }"], [["How should a custom component name begin?", "With a capital letter", "With a number", 0, "Capitalization distinguishes custom components from built-in lowercase tags."], ["What should a function component return?", "React UI such as JSX", "A package file", 0, "A component returns the UI React should render."], ["How can one component use another?", "Render it as a JSX element", "Call its CSS class", 0, "A component can be included as a JSX tag inside another component."]] ),
  uiTopic("react-import-export", "Importing and Exporting Components", "Split components into files and connect them with module imports and exports.", ["Exports make a component available to other modules. A default export is convenient when a file has one main component; named exports work well when a module provides several related items.", "Keep related components together when that makes them easier to find, and use clear file names. Import paths should match the project's module conventions."], ["export default function Header() { return <header>Library</header>; }", "export function Badge() { return <span>New</span>; }", "import Header, { Badge } from './Header';"], [["What does export allow?", "Another module to import a value", "A component to change CSS automatically", 0, "Exports make values available to other modules."], ["How is a named export imported?", "Inside braces using its exported name", "As a CSS selector", 0, "Named imports use braces and match the exported identifier."], ["What is one benefit of multiple component files?", "Related UI can be organized and reused", "The app no longer needs a build tool", 0, "Modules help organize code and make reuse clearer."]] ),
  uiTopic("react-jsx", "Writing Markup with JSX", "Describe UI with JSX while following its syntax rules.", ["JSX lets JavaScript files express a tree of UI elements. Unlike HTML, JSX requires tags to close and a component to return one parent element or a fragment.", "Use className for CSS classes and camelCase for many attributes. JSX is transformed by the project's build setup before the browser runs it."], ["return <img src=\"/cover.png\" alt=\"Book cover\" />;", "return <><h2>Notes</h2><p>Three saved items</p></>;", "return <button className=\"primary\">Continue</button>;"], [["How can a component return sibling JSX nodes?", "Wrap them in a parent or fragment", "Leave them adjacent without a wrapper", 0, "A single parent or fragment groups the returned nodes."], ["Which attribute sets a CSS class in JSX?", "className", "class", 0, "JSX uses className for the DOM class attribute."], ["What should be done with an empty JSX tag?", "Close it with />", "Leave it open", 0, "JSX requires tags to be properly closed."]] ),
  uiTopic("react-jsx-braces", "JavaScript in JSX with Curly Braces", "Insert JavaScript values and expressions into markup and attributes.", ["Curly braces switch from JSX markup to JavaScript expressions. They can display a variable, compute a label, or provide a value to an attribute.", "Use a quoted string for a fixed text value and braces for a JavaScript expression. Keep expressions readable; move complex calculations into named variables or functions."], ["const title = 'Weekly plan';\nreturn <h1>{title}</h1>;", "return <img src={coverUrl} alt={description} />;", "return <p>{items.length} items</p>;"], [["What do curly braces do inside JSX?", "Evaluate a JavaScript expression", "Create a CSS file", 0, "Braces let JSX read a JavaScript value or expression."], ["How do you pass a variable into an attribute?", "Use braces around the expression", "Put the variable name in quotes", 0, "Braces pass the variable's value rather than literal text."], ["Which expression displays the item count?", "{items.length}", "items.length as plain JSX text", 0, "The expression inside braces evaluates to the array length."]] ),
  uiTopic("react-passing-props", "Passing Props to a Component", "Configure a component by passing values from its parent.", ["Props are inputs passed from a parent to a child. They can include strings, numbers, objects, arrays, and callback functions.", "A component should treat props as read-only. If a value needs to change, the state owner updates it and sends the new value down."], ["function Tag({ label }) { return <span>{label}</span>; }", "<Tag label=\"In progress\" />", "function Score({ value }) { return <strong>{value} points</strong>; }"], [["Who supplies props to a component?", "Its parent", "The browser cache", 0, "A parent passes values through JSX attributes."], ["Should a child directly change its props?", "No, props are read-only inputs", "Yes, props are shared mutable state", 0, "The parent owns the input value and can send an updated prop."], ["Which prop value is appropriate?", "A number such as score={12}", "Only a string can be passed", 0, "Props can carry different JavaScript value types."]] ),
  uiTopic("react-conditional-rendering", "Conditional Rendering", "Show different UI based on the current data or state.", ["React uses regular JavaScript logic to choose which elements appear. Use if statements for larger branches, a conditional expression for two alternatives, and && when an optional section should appear.", "Be careful with values such as zero in a && expression, since JavaScript may render the zero. Make conditions explicit when the result is not a boolean."], ["if (loading) return <p>Loading…</p>;", "return isReady ? <Dashboard /> : <Setup />;", "return unreadCount > 0 ? <span>{unreadCount} unread</span> : null;"], [["What can choose between two UI alternatives?", "A conditional expression", "A CSS import only", 0, "The conditional operator can return one of two JSX results."], ["When is an if statement helpful?", "When a branch is larger or needs early return", "Only inside CSS", 0, "if statements are clear for larger control flow."], ["Why be careful with count && <Badge />?", "A zero count can render as visible text", "It always creates a list", 0, "JavaScript returns zero from the expression, and React can render it."]] ),
  uiTopic("react-rendering-lists", "Rendering Lists", "Turn arrays of data into repeated elements with stable keys.", ["Use map to transform each data item into a React element. A key helps React match each item with its earlier version when the collection changes.", "Use stable IDs from the data when possible. Array indexes can cause confusing updates when items are inserted, removed, or reordered."], ["const names = ['Asha', 'Milan'];\nreturn names.map(name => <li key={name}>{name}</li>);", "const cards = books.map(book => <BookCard key={book.id} book={book} />);", "const visible = products.filter(product => product.available);"], [["Which array method commonly creates a list of elements?", "map", "reduce only", 0, "map returns a new array of rendered elements."], ["What does a key help React do?", "Match list items across updates", "Choose a text color", 0, "Keys provide identity among sibling items."], ["Which key is usually more reliable for reorderable data?", "A stable item ID", "The current array position", 0, "Stable IDs remain connected to the same item as ordering changes."]] ),
  uiTopic("react-pure-components", "Keeping Components Pure", "Make rendering predictable by avoiding side effects and mutations during render.", ["A pure component returns the same UI for the same inputs and does not change values outside itself during render. This makes components easier to test and lets React render them reliably.", "Do not mutate props or shared arrays. Create new values for derived data, and put side effects in event handlers or the appropriate effect mechanism."], ["function Label({ name }) { return <span>{name}</span>; }", "const sorted = [...items].sort(compareItems);", "function addOne(value) { return value + 1; }"], [["What does a pure render do?", "Returns UI from inputs without side effects", "Changes a global variable", 0, "Purity makes output predictable for the same inputs."], ["How should a component sort a prop array?", "Copy it before sorting", "Mutate it directly", 0, "Copying avoids changing data owned by another component."], ["Where should a user-triggered side effect usually happen?", "In an event handler", "During every render", 0, "Event handlers respond to the interaction that caused the effect."]] ),
  uiTopic("react-ui-tree", "Your UI as a Tree", "Understand how component, render, and data relationships form trees.", ["React apps have a component tree: parents render children, and props flow down those relationships. Thinking in a tree helps locate where data belongs and how changes reach the screen.", "The rendered UI tree can differ from the source file structure. Use component relationships to reason about ownership, composition, and repeated subtrees."], ["App -> Header -> SearchBox", "App -> Catalog -> CategoryGroup -> ItemRow", "// A state owner can pass values to several child branches."], [["What does a component tree show?", "Parent-child rendering relationships", "Only CSS declarations", 0, "The tree represents how components compose into the interface."], ["In which direction do props usually flow?", "From parent to child", "From CSS to browser storage", 0, "Parents pass inputs down to rendered children."], ["Why think about the tree when placing state?", "It helps find a shared owner for consumers", "It removes the need for components", 0, "The nearest common parent is often a good place for shared state."]] ),
  uiTopic("react-describing-next", "What’s Next?", "Use components, JSX, props, and lists as a base for interactive interfaces.", ["Once a screen can be described from data, the next step is to make it respond to user actions. Events and state let React update the UI as information changes.", "Continue with small examples and trace how props and state affect the component tree. Keep derived values calculated from their source data."], ["// Add a button with an onClick handler.", "// Store a changing value with useState.", "// Pass the updated value to a child through props."], [["What makes a UI respond to user actions?", "Event handlers and state", "A key prop by itself", 0, "Events trigger updates and state stores changing values."], ["How should updated shared data reach child components?", "Through new props from the state owner", "By direct DOM edits", 0, "The parent passes updated values down through props."], ["What is a useful next practice step?", "Build a small interactive component", "Add unrelated configuration", 0, "A small interaction reinforces the rendering concepts."]] ),
]);

export const firstComponentLessons = chapter("Learn React · Describing the UI", [
  uiTopic("react-your-first-component", "Your First Component", "Create a small React component and use it to build a larger screen.", ["A React component is a JavaScript function that returns a description of UI. Components can be as small as a button or large enough to represent a whole page.", "The component's returned JSX can include browser elements and other React components. Building from small parts makes the interface easier to reuse and change."], ["function PageHeading() { return <h1>My reading shelf</h1>; }", "function BookCover() { return <img src=\"/images/book.png\" alt=\"Blue book cover\" />; }", "function ShelfPage() { return <main><PageHeading /><BookCover /></main>; }"], [["What does a React component usually return?", "A description of UI", "A browser tab", 0, "A component returns React UI, often written with JSX."], ["Can a component be a small interface part?", "Yes, such as one button", "No, it must be a full page", 0, "Components can represent small controls or larger screens."], ["How can a page use a component?", "Render it inside another component", "Put it in a CSS selector", 0, "Components can be composed by rendering one from another."]] ),
  uiTopic("react-components-building-blocks", "Components: UI Building Blocks", "Recognize how reusable components combine structure, styling, and behavior.", ["A web page is made from visible pieces such as headings, lists, images, and controls. A React component can package a useful piece of that interface into a named unit.", "Components can be nested and repeated. Reuse is most valuable when it makes the design clearer or lets one improvement update several places."], ["function Alert() { return <aside>Saved successfully</aside>; }", "function Menu() { return <nav><a href=\"/books\">Books</a></nav>; }", "function App() { return <><Menu /><Alert /></>; }"], [["What can a component represent?", "A reusable part of the interface", "Only a database", 0, "Components represent pieces of UI."], ["What does nesting components allow?", "Combining smaller parts into a larger view", "Changing JavaScript into CSS", 0, "Nesting is how component trees compose screens."], ["When is reuse helpful?", "When it clarifies repeated UI or shared behavior", "Whenever every HTML tag is wrapped", 0, "Reuse should improve clarity or consistency."]] ),
  uiTopic("react-defining-component", "Defining a Component", "Write an exported function with a capitalized name that returns JSX.", ["A function component uses standard JavaScript function syntax. Its name must begin with a capital letter when used as a JSX component.", "A component can return a single JSX element, a parent containing several elements, or a fragment. Keep the return value focused on the UI for that component."], ["function ProfileCard() { return <article><h2>Ravi</h2></article>; }", "function EmptyState() { return <>No books yet.</>; }", "export default function App() { return <ProfileCard />; }"], [["What capitalization should a component name use?", "A capital first letter", "All lowercase letters", 0, "Capitalization identifies custom JSX components."], ["Which function body is a component?", "A function that returns JSX", "A function that changes a CSS file", 0, "Function components return UI for React to render."], ["How can several sibling elements be returned?", "Wrap them in a parent or fragment", "Return them with no wrapper", 0, "JSX requires one root return value."]] ),
  uiTopic("react-export-component", "Step 1: Export the Component", "Make a component available to another module with an export.", ["JavaScript modules use exports to share functions and values with other files. A default export marks one primary value, while named exports allow several values from one module.", "Use the matching import syntax in the file that needs the component. Keep exported components intentionally public to the rest of the project."], ["export default function ProfileCard() { return <article />; }", "export function Divider() { return <hr />; }", "import ProfileCard, { Divider } from './ProfileCard';"], [["What does export do?", "Makes a module value available to import", "Adds a browser event", 0, "Exports share values between JavaScript modules."], ["How is a default export imported?", "As the default imported value", "Only inside square brackets", 0, "A default export can be imported with a local name."], ["How are named exports imported?", "Inside braces by their exported names", "As URL parameters", 0, "Named import syntax uses braces and matching names."]] ),
  uiTopic("react-define-function", "Step 2: Define the Function", "Give the component a clear name and keep its responsibility focused.", ["The function body describes what the component should render. A clear name helps teammates understand what role it plays in the component tree.", "Components are regular JavaScript functions, but React calls them as part of rendering. Use JSX tags to render components; avoid calling component functions directly as ordinary helpers."], ["function UserBadge() { return <span>Member</span>; }", "function LessonHeader() { return <header><h1>Lesson</h1></header>; }", "function Page() { return <LessonHeader />; }"], [["Why should a component have a clear name?", "It explains its role in the UI", "It changes its color", 0, "Names make component responsibilities easier to recognize."], ["How should a component normally be rendered?", "As a JSX element", "By manually calling it in another component's return", 0, "JSX lets React manage the component during rendering."], ["What should a component function describe?", "The UI for its responsibility", "The entire build pipeline", 0, "A component should focus on its part of the interface."]] ),
  uiTopic("react-add-markup", "Step 3: Add Markup", "Return JSX elements and format multi-line returns correctly.", ["JSX resembles HTML but follows JavaScript syntax rules. Use it to describe the elements and content a component should display.", "When returning multiple lines of JSX, wrap the expression in parentheses so JavaScript parses it as the return value. Remember to close tags and provide meaningful alt text for informative images."], ["return <p>Welcome back</p>;", "return (\n  <section>\n    <h2>Recent lessons</h2>\n    <ul><li>Components</li></ul>\n  </section>\n);", "return <img src=\"/avatar.png\" alt=\"Nila's profile\" />;"], [["What syntax lets a component describe markup in JavaScript?", "JSX", "SQL", 0, "JSX is the markup-like syntax used in React source."], ["Why wrap a multi-line return in parentheses?", "To keep the JSX expression together", "To make it a CSS selector", 0, "Parentheses ensure the JSX is parsed as the returned expression."], ["What should informative images include?", "Useful alternative text", "A React state setter", 0, "Alt text communicates the image meaning to people who cannot see it."]] ),
  uiTopic("react-use-component", "Using a Component", "Render a custom component from another component with JSX syntax.", ["Once defined, a component can be rendered by writing its name as a JSX tag. The capital letter tells React that it should look for a custom component.", "You can render the same component more than once. Each instance appears in the UI and can later receive different props."], ["function Tip() { return <p>Save your work often.</p>; }", "function Page() { return <main><Tip /><Tip /></main>; }", "function App() { return <Page />; }"], [["How do you render a custom component?", "Use a capitalized JSX tag", "Use a CSS class only", 0, "Custom components are referenced as capitalized JSX elements."], ["Can a component be used more than once?", "Yes, it can be rendered multiple times", "No, only once per app", 0, "React supports repeated component instances."], ["What does capitalized JSX tell React?", "This tag refers to a custom component", "It is an image URL", 0, "Capitalization distinguishes custom components from HTML tags."]] ),
  uiTopic("react-browser-output", "What the Browser Sees", "Understand that JSX becomes browser elements when React renders the component.", ["JSX is a developer-facing syntax. The build setup transforms it, and React creates browser DOM elements from the component output.", "The browser ultimately displays regular HTML elements styled by CSS. React manages updates when component inputs or state change."], ["function Title() { return <h1>Weekly plan</h1>; }", "function LinkButton() { return <button type=\"button\">Open</button>; }", "// JSX component -> React elements -> browser DOM"], [["Does the browser directly execute JSX syntax?", "No, project tooling transforms it first", "Yes, as CSS", 0, "The build setup transforms JSX for the runtime."], ["What elements does the browser ultimately display?", "DOM elements such as headings and buttons", "TypeScript interfaces", 0, "React renders browser elements into the DOM."], ["What can cause React to update rendered output?", "Changed component inputs or state", "A file name alone", 0, "Updates follow changes to the data React renders."]] ),
  uiTopic("react-nesting-organizing", "Nesting and Organizing Components", "Compose page layouts from components with clear roles.", ["A component tree expresses which parts contain other parts. A page component might render a header, navigation, content, and footer components.", "Keep components near the code that uses them when they are private to one feature. Move shared components to a common location when multiple areas need them."], ["function SiteHeader() { return <header>Fieldnotes</header>; }", "function MainContent() { return <main><h1>Explore</h1></main>; }", "function Layout() { return <><SiteHeader /><MainContent /></>; }"], [["What does a component tree help describe?", "How UI components are nested", "How network packets route", 0, "The tree shows parent-child composition."], ["Where can a feature-only component live?", "Near the feature that uses it", "Only in the root file", 0, "Local placement can make ownership easier to understand."], ["When should a component be shared?", "When multiple areas benefit from the same UI", "Whenever it has one HTML element", 0, "Shared components are useful when reuse improves consistency or clarity."]] ),
  uiTopic("react-first-recap", "Recap", "Review the steps for creating and composing a first component.", ["A component is a named function that returns UI. Export it when another module needs it, and use JSX to render it from a parent.", "Build larger screens by combining components. Give each component a clear purpose and follow JSX's closing-tag and single-root rules."], ["export function Avatar() { return <img alt=\"Profile\" src=\"/profile.png\" />; }", "function Profile() { return <><h2>Sam</h2><Avatar /></>; }", "export default function App() { return <Profile />; }"], [["What are the key pieces of a simple component?", "A function, a clear name, and returned UI", "A database and a CSS compiler", 0, "Function components return UI and use capitalized names."], ["How can components form a larger screen?", "By composing them in parent components", "By concatenating CSS class names only", 0, "Parents render children to build a larger interface."], ["When is an export needed?", "When another module must import the component", "Whenever it is used in the same file", 0, "Exports make a module's values available elsewhere."]] ),
  uiTopic("react-first-challenges", "Challenges", "Practice creating components and assembling a small page.", ["Try building a profile tile, a product card, and a page that uses both. Give each part a focused component name and valid JSX.", "After it renders, change the content and add a second instance. Check that the component remains understandable and accessible."], ["function ProfileTile() { return <article><h2>Lee</h2><p>Designer</p></article>; }", "function ProductCard() { return <article><h2>Desk lamp</h2><button>Save</button></article>; }", "function Gallery() { return <main><ProfileTile /><ProductCard /></main>; }"], [["What is a good first component challenge?", "Build one focused reusable UI piece", "Rewrite the browser", 0, "A small component is a good way to practice the basics."], ["What should you check after adding a second instance?", "That both render correctly and remain clear", "That component names are lowercase", 0, "Repeated use helps confirm the component is reusable."], ["What improves a component challenge beyond rendering?", "Meaningful structure and accessible content", "Removing all labels", 0, "Useful markup should also communicate meaning to users."]] ),
]);

export const componentModulesLessons = chapter("Learn React · Describing the UI", [
  uiTopic("react-import-export-components", "Importing and Exporting Components", "Organize reusable components in modules and import them where they are needed.", ["As a component tree grows, placing every function in one file can make the code hard to scan. JavaScript modules let you group related components and share them with imports and exports.", "A file can have one default export or several named exports. Match the import syntax to the export style, and keep file names and import paths consistent with the project."], ["// CatalogCard.jsx\nexport default function CatalogCard() { return <article>New books</article>; }", "// App.jsx\nimport CatalogCard from './CatalogCard';", "export function PriceTag() { return <span>$8</span>; }\nimport { PriceTag } from './PriceTag';"], [["Why split components into modules?", "To keep related code easier to scan and reuse", "To stop JSX from rendering", 0, "Modules can improve organization and reuse."], ["How is a named export imported?", "With braces around its exported name", "As a default import only", 0, "Named exports use braces and matching identifiers."], ["What must match for a default export import?", "The module path, while the local name can be chosen", "The import variable must match the file name", 0, "A default export can be imported under a chosen local name."]] ),
  uiTopic("react-root-component-file", "The Root Component File", "Find the component that starts a section of the app and how frameworks may organize it.", ["A small app often has an entry component such as App that renders the rest of its component tree. The browser entry point or framework then connects that component tree to a page.", "There is not always one App.js for the whole site. Frameworks with file-based routes may define a page component for each route, while shared layouts wrap several pages."], ["function App() { return <main><HomePage /></main>; }", "// A route file can export its page component as the default.", "// A shared layout can render a header and a child page."], [["What does a root component commonly render?", "The starting component tree for an app area", "Only a stylesheet", 0, "It provides the top of a component hierarchy."], ["Does every framework use one global App.js?", "No, route-based frameworks can define page components", "Yes, always", 0, "Project structure depends on the framework."], ["What can a shared layout provide?", "UI wrapped around multiple pages", "A replacement for imports", 0, "Layouts commonly contain shared page structure."]] ),
  uiTopic("react-export-import-one", "Exporting and Importing a Component", "Move a component into a file and connect it to the module that uses it.", ["To share a component, define it in a module and export it. Then import it from the module that needs to render it.", "Default exports are convenient for a module's primary value. Named exports are explicit and work well when a file offers several related helpers or components."], ["// Notice.jsx\nexport default function Notice() { return <p>All caught up</p>; }", "// Dashboard.jsx\nimport Notice from './Notice';", "// Shared.jsx\nexport function Divider() { return <hr />; }\nexport function Label() { return <span>Topic</span>; }"], [["What connects a component across files?", "An export and a matching import", "A CSS comment", 0, "Modules share component functions through exports and imports."], ["Can a default import use a different local name?", "Yes", "No, it must match the file name", 0, "The default export's local import name is chosen by the importer."], ["When are named exports useful?", "When a module shares several explicit values", "Only for images", 0, "Named exports make each imported value explicit."]] ),
  uiTopic("react-export-multiple", "Export Multiple Components from One File", "Group closely related components while keeping exports clear.", ["A module can export multiple components by name. This can work well when components belong to one small feature and are commonly used together.", "If a file becomes difficult to navigate or components are reused independently, split them into separate modules. The goal is a structure that makes ownership and reuse clear."], ["export function Toolbar() { return <nav />; }", "export function ToolButton() { return <button>Run</button>; }", "import { Toolbar, ToolButton } from './Tools';"], [["How can a module expose several components?", "Use named exports", "Use multiple default exports", 0, "A module may have multiple named exports."], ["How many default exports can a module have?", "One", "Any number", 0, "A module has at most one default export."], ["When might components deserve separate files?", "When they grow or are reused independently", "Whenever they share a color", 0, "Separate files can clarify larger or independently reused components."]] ),
  uiTopic("react-import-export-recap", "Recap and Challenges", "Practice choosing file boundaries and connecting component modules.", ["Use a root or page component to compose the screen. Export components that need to be reused from another module, then import them using the matching syntax.", "Try splitting a small screen into a page, a card, and a button. Choose default or named exports consistently and keep import paths easy to follow."], ["// Page.jsx imports its default Card component.", "// Components.jsx exports named Card and Badge functions.", "// App.jsx composes <Page /> inside a shared layout."], [["What should guide a component file boundary?", "Whether it improves clarity and reuse", "The number of letters in its name", 0, "File organization should make code easier to understand."], ["What must correspond between named export and import?", "The exported identifier", "The CSS color", 0, "Named imports refer to the exact exported name."], ["What is one useful challenge for this lesson?", "Split a page into a few related modules", "Put every component in a global variable", 0, "A small refactor helps practice module boundaries."]] ),
]);

export const jsxLessons = chapter("Learn React · Describing the UI", [
  uiTopic("react-writing-jsx", "Writing Markup with JSX", "Use JSX to describe the interface a component should render.", ["JSX is a syntax extension that lets JavaScript files express a tree of UI elements. It looks similar to HTML, but follows JavaScript parsing rules and supports dynamic values.", "Putting rendering logic near its markup can make a component easier to understand: the condition and the UI it controls stay together. JSX is a syntax choice; React components can be authored in other ways too."], ["function Message() { return <p>Welcome to the studio.</p>; }", "function Status({ ready }) { return <span>{ready ? 'Ready' : 'Waiting'}</span>; }", "function Page() { return <main><h1>Notes</h1><Message /></main>; }"], [["What is JSX?", "A JavaScript syntax for describing UI", "A CSS selector language", 0, "JSX lets JavaScript express markup-like UI structure."], ["Can JSX display dynamic values?", "Yes, with JavaScript expressions", "No, it only accepts fixed strings", 0, "JSX can include expressions such as variables and conditions."], ["Are JSX and React the same thing?", "No, JSX is syntax and React is a UI library", "Yes, they are one tool", 0, "They are separate technologies often used together."]] ),
  uiTopic("react-jsx-markup-js", "JSX: Putting Markup into JavaScript", "Keep a component's rendering decisions close to the elements they control.", ["Interactive interfaces often show different content depending on state or user input. JSX lets a component express that relationship in one place.", "Keep each component focused so unrelated regions remain easy to change independently. Split components when their responsibilities or reuse patterns differ."], ["function LoginHint({ signedIn }) { return <p>{signedIn ? 'Your account is ready' : 'Sign in to continue'}</p>; }", "function SubmitButton({ busy }) { return <button disabled={busy}>{busy ? 'Saving…' : 'Save'}</button>; }", "function Sidebar() { return <aside><LoginHint signedIn={false} /></aside>; }"], [["Why place rendering logic near its markup?", "The condition and UI it controls stay together", "It removes all JavaScript", 0, "Keeping related logic and markup together can make changes easier to follow."], ["When is a component split useful?", "When responsibilities are distinct or reused", "For every HTML element", 0, "Component boundaries should clarify responsibility or reuse."], ["What controls the button label in the example?", "The busy prop", "The stylesheet filename", 0, "The prop chooses which text the JSX displays."]] ),
  uiTopic("react-convert-html-jsx", "Converting HTML to JSX", "Adapt existing HTML markup to JSX syntax before placing it in a component.", ["HTML can be a useful starting point, but JSX requires one returned root, closed tags, and JavaScript-style attribute names. Convert markup carefully instead of pasting a large page without checking it.", "Use the editor's diagnostics to find invalid attributes and missing closing tags. Preserve semantic structure and meaningful alternative text during the conversion."], ["// HTML: class=\"card\" -> JSX: className=\"card\"", "// HTML: <img ...> -> JSX: <img ... />", "return <section><h2>Archive</h2><p>Five entries</p></section>;"], [["What usually needs changing when HTML becomes JSX?", "Attributes and tag syntax", "The visible words only", 0, "JSX has stricter tag and attribute conventions."], ["How should an image tag be written in JSX?", "As a closed element such as <img />", "As an unclosed start tag", 0, "JSX requires tags to close."], ["What should remain during conversion?", "Semantic meaning and useful alt text", "Only visual appearance", 0, "Accessible and semantic structure should be preserved."]] ),
  uiTopic("react-jsx-single-root", "Rule 1: Return a Single Root Element", "Wrap sibling JSX elements in one parent or a fragment.", ["A component returns one expression. If its UI has several sibling elements, group them with a meaningful container or a fragment.", "Use a fragment when the group needs no extra DOM element. Choose a semantic container when the content has a meaningful role."], ["return <><h2>Tasks</h2><ul><li>Read</li></ul></>;", "return <section><h2>Profile</h2><p>Member since 2024</p></section>;", "const panel = <main><Header /><Content /></main>;"], [["Why group sibling elements?", "A component returns one root expression", "The browser allows only one element total", 0, "JSX components need one returned root expression."], ["When is a fragment useful?", "When grouping is needed without an extra DOM node", "When a CSS class is required", 0, "Fragments group children without adding a wrapper element."], ["When should a semantic container be used?", "When the content has a meaningful document role", "For every group of two elements", 0, "Semantic elements communicate structure to browsers and assistive tools."]] ),
  uiTopic("react-jsx-close-tags", "Rule 2: Close All the Tags", "Close paired tags and self-close elements that have no children.", ["JSX checks tag structure strictly. Elements with children need a closing tag, and elements without children use a self-closing form.", "Careful nesting makes the element tree clear and helps prevent confusing render errors."], ["<p>Short note</p>", "<img src=\"/map.png\" alt=\"Town map\" />", "<section><h2>Updates</h2><ul><li>Published</li></ul></section>"], [["How should an element with children be written?", "With an opening and closing tag", "With only an opening tag", 0, "Paired tags must have a matching close."], ["How is an element with no children closed?", "With />", "With a semicolon only", 0, "Self-closing JSX elements use slash-angle syntax."], ["What does careful nesting help maintain?", "A clear element tree", "A fixed network connection", 0, "Nesting represents the UI hierarchy."]] ),
  uiTopic("react-jsx-camelcase", "Rule 3: Use camelCase Attributes", "Write JSX attributes using JavaScript-friendly names.", ["Many JSX attributes use camelCase because they map to JavaScript properties. A common example is className instead of the HTML class attribute.", "Some attributes retain their familiar spelling, while event props use names such as onClick. Let editor suggestions help identify the expected prop name."], ["<div className=\"notice\">Saved</div>", "<button onClick={handleOpen}>Open</button>", "<label htmlFor=\"email\">Email</label>"], [["Which JSX attribute adds a CSS class?", "className", "class", 0, "JSX uses className for the class property."], ["How is a click handler named in JSX?", "onClick", "onclick only", 0, "React event props use camelCase names such as onClick."], ["Which attribute connects a label to an input id?", "htmlFor", "for", 0, "JSX uses htmlFor as the property name for a label association."]] ),
  uiTopic("react-jsx-converter", "Pro-tip: Use a JSX Converter", "Use conversion tools as a starting point and review the output carefully.", ["A converter can speed up changing a large HTML snippet into JSX, especially when many attributes need adjustment. It may not understand the intent or accessibility needs of the page.", "Review the result for semantic elements, closed tags, className, event names, and a single root. Keep only code you understand and trust."], ["// Convert a small snippet first and inspect the result.", "// Check alt text and label associations after conversion.", "// Run the app and fix diagnostics rather than blindly accepting output."], [["What is a converter useful for?", "Speeding up mechanical syntax changes", "Choosing the app's data model", 0, "Converters can help with repetitive syntax conversion."], ["What should be reviewed after conversion?", "Accessibility and JSX structure", "Only the file name", 0, "Tools cannot reliably infer semantic intent or accessibility quality."], ["Should converter output be accepted without review?", "No, inspect and understand it", "Yes, always", 0, "Generated code should be reviewed before use."]] ),
  uiTopic("react-jsx-recap-challenges", "Recap and Challenges", "Practice converting a small markup block and displaying dynamic data.", ["JSX is markup-like JavaScript syntax with one root, closed tags, and JavaScript-style attributes. Curly braces can insert dynamic expressions.", "Try converting a small card or list, then add a condition or variable. Check the app output and editor diagnostics."], ["function Greeting({ name }) { return <h2>Hello, {name}</h2>; }", "function Card() { return <article className=\"card\"><h2>Project</h2></article>; }", "function List({ rows }) { return <ul>{rows.map(row => <li key={row.id}>{row.label}</li>)}</ul>; }"], [["Which three JSX habits were covered?", "One root, closed tags, JavaScript-style attributes", "Global variables, inline CSS, and scripts", 0, "These are key structural conventions for JSX."], ["How do you insert a variable into JSX text?", "Use curly braces", "Use square brackets", 0, "Curly braces evaluate JavaScript expressions in JSX."], ["What should be checked after writing JSX?", "The rendered result and diagnostics", "Only the component name", 0, "Running the app and reading diagnostics catches issues."]] ),
]);

export const jsxCurlyLessons = chapter("Learn React · Describing the UI", [
  uiTopic("react-jsx-curly-braces", "JavaScript in JSX with Curly Braces", "Move between fixed JSX text and JavaScript values when building dynamic UI.", ["JSX can include JavaScript expressions inside curly braces. This lets a component display values from variables, calculate labels, and pass dynamic properties.", "Quoted attributes represent fixed strings. Use braces when the value should come from a variable or expression, and keep complex logic in named variables for readability."], ["const heading = 'Your reading plan';\nreturn <h1>{heading}</h1>;", "const imageAlt = 'A stack of books';\nreturn <img alt={imageAlt} src={coverUrl} />;", "return <p>{books.length} books saved</p>;"], [["What do curly braces enable inside JSX?", "JavaScript expressions", "CSS selectors", 0, "Curly braces evaluate JavaScript expressions in JSX."], ["What does a quoted attribute value represent?", "A fixed string", "A variable lookup", 0, "Quoted values are literal strings."], ["When should a variable be placed in braces?", "When JSX should use its value", "When the variable name should appear as text", 0, "Braces evaluate the variable instead of rendering its name literally."]] ),
  uiTopic("react-jsx-quoted-strings", "Passing Strings with Quotes", "Use quotes for literal text in JSX attributes.", ["A quoted attribute is a fixed string value. This is useful for class names, labels, and other content that does not need to change based on JavaScript data.", "If an attribute should vary, store the value in a variable and pass that expression with braces instead."], ["<button type=\"button\">Open menu</button>", "<img className=\"thumbnail\" alt=\"Mountain path\" />", "<a href=\"/library\">Browse library</a>"], [["What does className=\"tile\" pass?", "The literal string tile", "A variable named tile", 0, "Quotes provide the text value directly."], ["Which is a literal string attribute?", "alt=\"Course cover\"", "alt={coverDescription}", 0, "Quoted content is a fixed string."], ["How can an attribute use changing data?", "Use a JavaScript expression in braces", "Keep the value in quotes", 0, "Braces let the attribute receive a dynamic value."]] ),
  uiTopic("react-jsx-brace-window", "Using Curly Braces: A Window into JavaScript", "Read values and calculate simple expressions inside JSX.", ["Braces inside JSX switch into JavaScript expression mode. You can reference variables, access properties, or compute a small value for display.", "Only expressions that produce a value belong directly between braces. Statements such as if blocks should be written outside JSX or expressed using a conditional expression."], ["const learner = { name: 'Noor' };\nreturn <h2>Welcome, {learner.name}</h2>;", "return <p>{price * quantity} credits</p>;", "return <p>{isNew ? 'Recently added' : 'In the library'}</p>;"], [["Which kind of JavaScript can go directly in JSX braces?", "An expression that produces a value", "A function declaration statement", 0, "JSX braces evaluate expressions."], ["What does {learner.name} display?", "The name property's value", "The literal text learner.name", 0, "The expression reads the object's property."], ["How can two text alternatives be selected inside JSX?", "A conditional expression", "A for statement", 0, "A conditional expression returns one value for the UI."]] ),
  uiTopic("react-jsx-brace-locations", "Where to Use Curly Braces", "Use braces in text positions and attribute values where an expression is expected.", ["In JSX text, braces let a component include a dynamic result among static words. In an attribute, braces provide a JavaScript value instead of a literal string.", "Do not wrap static strings in braces unless you need a JavaScript expression. Clear distinction helps readers see which values are dynamic."], ["<p>Hello, {studentName}</p>", "<img src={imageUrl} alt={imageLabel} />", "<button disabled={isSaving}>Save</button>"], [["Where can JSX braces place dynamic values?", "In text and attribute expression positions", "Inside tag names", 0, "Braces work in JSX text and attribute values."], ["What does disabled={isSaving} use?", "The boolean value of isSaving", "The text 'isSaving'", 0, "The expression evaluates to a JavaScript value."], ["How should a fixed string usually be written?", "As a quoted JSX value", "As a variable expression", 0, "Quotes make literal strings clear."]] ),
  uiTopic("react-jsx-double-curly", "Using Double Curly Braces: CSS and Other Objects", "Pass an object expression, often for inline styles, using braces around an object literal.", ["A style prop expects an object whose property names use JavaScript naming, such as backgroundColor. JSX uses one brace pair to enter JavaScript; the inner braces create the object literal.", "Inline style values are useful when they depend on data, but regular CSS classes are often better for reusable visual rules."], ["<p style={{ color: 'teal' }}>Available</p>", "const badgeStyle = { backgroundColor: '#eef', padding: 8 };\nreturn <span style={badgeStyle}>New</span>;", "<div style={{ width: cardWidth, borderRadius: 12 }} />"], [["Why do you see two brace pairs in style={{ color: 'teal' }}?", "One enters JavaScript and one creates an object", "One closes the HTML tag", 0, "The outer braces mark an expression and the inner braces form an object literal."], ["How is a CSS property written in a style object?", "In camelCase such as backgroundColor", "In a selector such as .background-color", 0, "Style object keys use JavaScript property naming."], ["When are inline style objects especially useful?", "When a style value depends on data", "For every reusable design rule", 0, "Dynamic style values can be supplied from JavaScript data."]] ),
  uiTopic("react-jsx-objects", "More Fun with JavaScript Objects and Curly Braces", "Use object properties and array methods to render data-driven content.", ["Once expressions are familiar, JSX can read nested object values and map arrays into repeated elements. Keep data transformations readable and use stable keys for rendered lists.", "You can compute a value before the return when an expression becomes too complex to read inline."], ["const course = { title: 'React UI', level: 'Beginner' };\nreturn <h2>{course.title} · {course.level}</h2>;", "const labels = ['Props', 'JSX'];\nreturn <ul>{labels.map(label => <li key={label}>{label}</li>)}</ul>;", "const total = cart.reduce((sum, item) => sum + item.price, 0);\nreturn <p>Total: {total}</p>;"], [["How can an array become repeated JSX elements?", "Map its items to elements", "Place the array directly in an attribute name", 0, "map transforms each item into a rendered element."], ["Why does a mapped list need keys?", "To identify items across updates", "To calculate their text color", 0, "Keys help React match sibling elements between renders."], ["When should a complex calculation move outside JSX?", "When a named variable makes the markup easier to read", "Never", 0, "Named intermediate values can improve readability."]] ),
  uiTopic("react-jsx-curly-recap", "Recap and Challenges", "Practice combining literal text with dynamic JavaScript values in JSX.", ["Use quotes for fixed strings and curly braces for JavaScript expressions. Object style values use an object literal inside the expression.", "Practice with a profile card, a status message, and a list. Keep the markup readable and validate the data before using it if it comes from an external source."], ["const name = 'Ira';\nreturn <h2>Hello, {name}</h2>;", "return <button disabled={loading}>{loading ? 'Working…' : 'Submit'}</button>;", "return <ul>{topics.map(topic => <li key={topic.id}>{topic.title}</li>)}</ul>;"], [["How do you distinguish literal and dynamic attribute values?", "Quotes are literal; braces evaluate expressions", "Both always mean a variable", 0, "Quotes pass text directly while braces evaluate JavaScript."], ["What should dynamic list items include?", "Stable keys", "Double quotes around JSX tags", 0, "Keys identify list siblings as the data changes."], ["What is one good challenge for this lesson?", "Build a card using object properties and expressions", "Remove all JavaScript from the component", 0, "A data-driven card practices the central JSX expression pattern."]] ),
]);

export const propsLessons = chapter("Learn React · Describing the UI", [
  uiTopic("react-passing-props-lesson", "Passing Props to a Component", "Send information from a parent component to configure its child components.", ["Props are values passed to a component through JSX attributes. They resemble HTML attributes, but custom components can receive JavaScript values such as objects, arrays, numbers, and functions.", "A parent chooses the values; a child reads them to describe its UI. Props are read-only inputs, so changing shared information should happen through the owner of that data."], ["function Pill({ text }) { return <span>{text}</span>; }", "<Pill text=\"In review\" />", "<Avatar person={{ name: 'Mira' }} size={72} />"], [["What are props?", "Inputs passed to a component", "A CSS file", 0, "Props carry information from parent to child."], ["Can a custom component receive an object prop?", "Yes", "No, only strings are allowed", 0, "Props can carry any JavaScript value."], ["Who chooses the value passed as a prop?", "The parent component", "The browser stylesheet", 0, "The parent supplies values through JSX attributes."]] ),
  uiTopic("react-familiar-props", "Familiar Props", "Recognize props on built-in elements and pass similar inputs to custom components.", ["Built-in elements accept props such as className, src, alt, and width. React maps these values to browser element properties.", "Custom components define their own prop names and meanings. Use clear names that describe what the child needs to render."], ["<img src={coverUrl} alt=\"Course cover\" width={160} />", "<button type=\"button\" disabled={locked}>Continue</button>", "<UserBadge name=\"Mina\" role=\"Editor\" />"], [["Which is a common image prop?", "alt", "onPaint", 0, "alt provides alternative text for an image."], ["Can a custom component define its own prop names?", "Yes", "No, only HTML names are allowed", 0, "Custom components can accept application-specific inputs."], ["Why use descriptive prop names?", "They clarify what information the child receives", "They automatically create routes", 0, "Clear names make component use easier to understand."]] ),
  uiTopic("react-props-pass", "Pass Props to a Component", "Add attributes to a component tag to provide values for its props.", ["A parent passes props in JSX. Strings can be quoted; numbers, booleans, objects, and variables use curly braces.", "The values travel down to the child that is rendered by the parent. Keep the data source clear so updates have one owner."], ["<Rating value={4} />", "<Profile name=\"Ari\" active={true} />", "<Product item={selectedProduct} />"], [["How is a number passed as a prop?", "With a JavaScript expression in braces", "Only inside quotes", 0, "Braces pass a numeric value rather than text."], ["How is a fixed string commonly passed?", "As a quoted JSX attribute", "As a function declaration", 0, "Quotes provide a literal string prop."], ["Which direction do props usually flow?", "From parent to child", "From child to parent automatically", 0, "A parent supplies props to its rendered child."]] ),
  uiTopic("react-props-read", "Read Props Inside the Child", "Receive props as a function parameter and use them to render the child UI.", ["A function component receives one props object. Destructuring in the parameter lets the component read named values directly.", "The child should use the supplied values rather than hard-code a separate version of the same information."], ["function Greeting({ name }) { return <p>Hello, {name}</p>; }", "function Badge({ count, label }) { return <span>{label}: {count}</span>; }", "function UserCard({ user }) { return <h2>{user.displayName}</h2>; }"], [["What does destructuring { name } in a parameter do?", "Reads the name property from props", "Creates a global variable", 0, "It extracts the name field from the props object."], ["Why render a prop value instead of hard-coding it?", "The component can display different data each use", "It removes the parent", 0, "Props make a component configurable and reusable."], ["What object does a component receive?", "A props object", "A stylesheet object only", 0, "React supplies the component's inputs as props."]] ),
  uiTopic("react-props-default", "Specify a Default Value for a Prop", "Provide a fallback when a parent leaves a prop undefined.", ["A default parameter value can make a component useful when an optional prop is omitted. The default applies when the value is undefined.", "Choose a fallback that makes sense for the UI. A default does not replace validation for untrusted data."], ["function Avatar({ size = 48 }) { return <img width={size} height={size} alt=\"Profile\" />; }", "function Greeting({ name = 'there' }) { return <p>Hello, {name}</p>; }", "function Tag({ tone = 'neutral' }) { return <span data-tone={tone}>Status</span>; }"], [["When does a destructured default value apply?", "When the prop is undefined or omitted", "Whenever the prop is zero", 0, "Defaults apply to undefined values."], ["What should a prop default be?", "A sensible fallback for the interface", "A random value", 0, "Defaults should provide intentional behavior."], ["Does a default validate external data?", "No", "Yes, completely", 0, "Defaults do not replace runtime validation."]] ),
  uiTopic("react-props-spread", "Forward Props with the JSX Spread Syntax", "Pass several known object properties to a child using a spread.", ["The spread syntax can forward properties from an object into a component. This is convenient when the object already matches the child's prop shape.", "Use it thoughtfully: forwarding every property can make the child's inputs harder to see and may pass values the component does not need."], ["const options = { size: 40, label: 'Avatar' };\n<Avatar {...options} />", "function Link({ href, children, ...rest }) { return <a href={href} {...rest}>{children}</a>; }", "// Prefer explicit props when they make the component contract clearer."], [["What does {...options} do in JSX?", "Passes object properties as props", "Turns the object into CSS", 0, "Spread syntax forwards enumerable properties as attributes."], ["When is spreading an object convenient?", "When it already matches the component's prop shape", "When the child should receive unrelated data", 0, "A matching object can be forwarded compactly."], ["What is a risk of spreading a large object?", "The child may receive unclear or unintended props", "It removes all props", 0, "Broad forwarding can hide the component contract."]] ),
  uiTopic("react-props-children", "Passing JSX as Children", "Use the special children prop to place nested content inside a component.", ["JSX nested between a component's opening and closing tags becomes its children prop. A wrapper can render children inside a layout or visual container.", "Children let a component provide a frame while the parent chooses the inner content. Use a suitable React type in TypeScript when describing children."], ["function Panel({ children }) { return <section className=\"panel\">{children}</section>; }", "<Panel><p>Details go here.</p></Panel>", "<Panel><h2>Schedule</h2><ul><li>Monday</li></ul></Panel>"], [["Where does nested JSX appear in a component?", "In the children prop", "In the key prop", 0, "Nested content is passed as children."], ["What is a wrapper component useful for?", "Providing shared layout around chosen content", "Replacing the child content automatically", 0, "A wrapper can control presentation while callers provide inner content."], ["Who chooses the nested panel content?", "The parent using the component", "The browser", 0, "The parent places JSX between the component tags."]] ),
  uiTopic("react-props-time", "How Props Change Over Time", "Understand that a child renders again when its parent provides new props.", ["Props are current inputs, not values a child changes itself. When a parent updates its data and renders again, the child receives the new prop values.", "Avoid copying props into state unless you need a separate, intentionally managed value. Derived UI should normally be calculated from the current props."], ["function Greeting({ name }) { return <p>Welcome, {name}</p>; }", "<Greeting name={currentUser.name} />", "// When currentUser changes, the parent supplies the new name."], [["What happens when a parent passes a new prop value?", "The child can render using the updated input", "The child changes the parent's source data", 0, "The parent controls the prop and provides updated inputs."], ["Should props normally be mutated by a child?", "No, they are read-only inputs", "Yes, they are shared state", 0, "Children should not mutate props."], ["What should derived display content use?", "The current prop value", "A stale copied value", 0, "Using current props keeps the display aligned with parent data."]] ),
  uiTopic("react-props-recap-challenges", "Recap and Challenges", "Practice building configurable components with clear prop contracts.", ["Parents pass values down, children read them, and nested JSX becomes children. Default values handle omitted optional inputs, while spread syntax can forward a matching object.", "Try a reusable profile card with a name, avatar description, optional role, and nested action button. Change the parent data and confirm the child updates from its new props."], ["function ProfileCard({ name, role = 'Member', children }) { return <article><h2>{name}</h2><p>{role}</p>{children}</article>; }", "<ProfileCard name=\"Tariq\"><button>Message</button></ProfileCard>", "const person = { name: 'Tariq', role: 'Mentor' };\n<ProfileCard {...person} />"], [["What are the main ways a parent can configure a child?", "Props and nested children", "Directly editing the child's DOM", 0, "Props and children provide component inputs and content."], ["What should a reusable component's props communicate?", "The inputs needed to render its UI", "Every global app value", 0, "A clear contract names the information the component needs."], ["How can you check that props work over time?", "Change parent data and observe the child update", "Reload CSS only", 0, "Updated parent values should flow to the child on render."]] ),
]);

export const conditionalLessons = chapter("Learn React · Describing the UI", [
  uiTopic("react-conditional-rendering", "Conditional Rendering", "Choose which UI to display by using JavaScript conditions in a component.", ["A component can show different content depending on props or state. React uses regular JavaScript control flow, so you can choose between JSX branches with if, a conditional expression, or a logical operator.", "Pick the form that keeps the UI behavior easy to understand. Make conditions explicit, especially when values such as zero or an empty string could be rendered unexpectedly."], ["if (loading) return <p>Loading…</p>;", "return signedIn ? <Dashboard /> : <SignIn />;", "return hasNotice ? <Notice /> : null;"], [["What can determine which JSX is returned?", "A JavaScript condition", "A CSS filename", 0, "JavaScript conditions choose the component output."], ["Which syntax can choose between two branches inline?", "The conditional operator", "A module import", 0, "The ternary operator returns one of two expressions."], ["Why be careful with logical conditions in JSX?", "JavaScript may return a visible value such as zero", "React ignores every condition", 0, "The left side's value can be rendered when it is falsy but not false/null."]] ),
  uiTopic("react-conditional-return-jsx", "Conditionally Returning JSX", "Use if statements or early returns to select a component's output.", ["An if statement can choose a different JSX tree for each case. Early returns are useful for loading, missing data, or access states before the main content.", "Keep the branches complete and meaningful. If two branches share most of their markup, consider rendering the shared structure once and conditionally changing a small part."], ["if (error) return <p role=\"alert\">Could not load the page.</p>;", "if (!record) return <p>Record not found.</p>;", "return <article><h2>{title}</h2>{isPublished ? <p>Live</p> : <p>Draft</p>}</article>;"], [["When is an early return useful?", "For a distinct loading or error state", "For importing CSS", 0, "Early returns keep separate UI states clear."], ["What can an if statement return?", "Different JSX for different conditions", "Only a boolean", 0, "A component can return a different UI branch."], ["What should you consider when branches share most markup?", "Render shared structure once and vary the needed part", "Duplicate everything automatically", 0, "Shared structure can reduce duplication and improve clarity."]] ),
  uiTopic("react-conditional-null", "Conditionally Returning Nothing with null", "Return null when a component should contribute no visible UI.", ["A component may return null when it has nothing to display. This can keep the condition close to the component that owns the display decision.", "Use null for an intentional empty result, not as a way to hide an error or skip required content without explanation."], ["if (!isVisible) return null;", "function OptionalBadge({ label }) { return label ? <span>{label}</span> : null; }", "function EmptyPanel({ enabled }) { if (!enabled) return null; return <aside>Panel is open</aside>; }"], [["What does returning null mean for a component?", "It renders no UI", "It renders the word null", 0, "React treats null as no rendered element."], ["When might a component return null?", "When it has no visible content for the current state", "To replace required labels everywhere", 0, "Null is suitable for an intentional empty rendering case."], ["Should null hide an unexpected error silently?", "No, handle the error state clearly", "Yes, always", 0, "Errors should be represented or reported rather than silently hidden."]] ),
  uiTopic("react-conditional-include", "Conditionally Including JSX", "Add an optional part of a larger tree only when its condition is met.", ["Sometimes the page stays mostly the same and only one section appears conditionally. A ternary can choose between an element and null, while && can include an element for a truthy condition.", "Choose a condition that is clearly boolean. The && shortcut can render a numeric zero, so compare counts explicitly when zero is possible."], ["{hasAttachment ? <Attachment /> : null}", "{showDetails && <Details />}", "{unreadCount > 0 && <Badge count={unreadCount} />}"], [["What does a ternary with null do?", "Includes the element in one branch and nothing in the other", "Always renders both branches", 0, "The condition chooses an element or null."], ["When is && useful in JSX?", "For including an element when a condition is true", "For returning two alternatives", 0, "Logical AND can conditionally include one expression."], ["How can you avoid rendering zero from {count && ...}?", "Use count > 0 as the condition", "Convert zero to a component name", 0, "An explicit comparison produces a boolean condition."]] ),
  uiTopic("react-conditional-ternary", "Conditional (Ternary) Operator", "Use condition ? A : B to select one of two JSX expressions.", ["The conditional operator evaluates a condition and returns one of two values. It fits short alternatives that are easy to read in place.", "For many branches or complex logic, use if statements or compute a named variable before the return."], ["return isOnline ? <span>Online</span> : <span>Offline</span>;", "<button>{saving ? 'Saving…' : 'Save'}</button>", "const view = compact ? <CompactCard /> : <FullCard />;\nreturn view;"], [["How many alternatives does a ternary select?", "Two", "Any number without nesting", 0, "The ternary operator has one true and one false branch."], ["What does the condition determine?", "Which branch's value is returned", "Which file is imported", 0, "The condition selects the first or second expression."], ["When is an if statement clearer than nested ternaries?", "When there are several complex branches", "When there is one short label", 0, "Complex branching is easier to follow with explicit control flow."]] ),
  uiTopic("react-conditional-and", "Logical AND Operator", "Use && for concise inclusion when the left condition is boolean.", ["In JavaScript, && returns the right side when the left side is truthy. React can render the returned JSX, so this is a short way to include optional content.", "Do not use a possibly numeric value directly if zero could appear. Write an explicit boolean comparison for clarity."], ["{isExpanded && <section>More information</section>}", "{items.length > 0 && <ItemList items={items} />}", "{hasError && <p role=\"alert\">Try again.</p>}"], [["What must be true for the right side of && to be returned?", "The left side is truthy", "The component name is uppercase", 0, "Logical AND returns the right operand when the left is truthy."], ["What is a risk of {items.length && <List />}?", "A zero length may render as text", "It always hides the list", 0, "The expression can return numeric zero."], ["What is a clear condition for rendering a non-empty list?", "items.length > 0", "items.length as a tag", 0, "The comparison produces a boolean condition."]] ),
  uiTopic("react-conditional-variable", "Conditionally Assigning JSX to a Variable", "Compute a branch before the return when it makes the component easier to read.", ["A component can assign JSX to a local variable using if/else, then include that variable in its returned tree. This works well when the branching logic is longer than a short expression.", "A named variable can make the return markup simpler, especially when the surrounding layout stays the same."], ["let panel;\nif (loading) panel = <Spinner />;\nelse panel = <Results />;", "const action = canEdit ? <EditButton /> : <ReadOnlyLabel />;", "return <main><Header />{panel}<Footer /></main>;"], [["Why assign JSX to a variable first?", "To keep complex branching separate from return markup", "To stop React from rendering it", 0, "A local value can make a long conditional easier to read."], ["Can an if statement assign JSX to a variable?", "Yes", "No, only ternaries return JSX", 0, "JavaScript can assign a JSX expression to a variable."], ["When is this pattern useful?", "When surrounding layout is shared across branches", "When no condition exists", 0, "It keeps common layout together while varying one section."]] ),
  uiTopic("react-conditional-recap", "Recap", "Choose conditional syntax based on the number and complexity of UI branches.", ["Use if/else for clear control flow, ternary for two short alternatives, && for optional inclusion with a boolean condition, and null for no output.", "Keep conditions readable and watch out for values like zero that JavaScript may return from logical expressions."], ["if (busy) return <Spinner />;", "return enabled ? <Editor /> : <Preview />;", "return count > 0 && <CountBadge count={count} />;"], [["Which form fits several complex branches?", "if/else control flow", "A deeply nested ternary", 0, "Explicit branches are usually clearer when logic grows."], ["Which return value renders no UI?", "null", "undefined text", 0, "React renders null as no output."], ["What should be checked when using && with a number?", "Whether zero might be rendered", "Whether the number is in a filename", 0, "A falsy numeric zero can become the expression result."]] ),
  uiTopic("react-conditional-challenges", "Challenges", "Practice showing status, optional details, and alternative actions.", ["Build a lesson tile that shows a completion label, optional details, and either a Start or Review button. Keep each branch short and clear.", "Test boundary cases such as no details, zero notifications, loading, and error states so the UI handles more than the happy path."], ["const action = done ? <button>Review</button> : <button>Start</button>;", "{details && <p>{details}</p>}", "{notifications > 0 ? <Badge count={notifications} /> : null}"], [["Which case is important for a notification count?", "Zero notifications", "Only a count of 100", 0, "Zero often reveals mistakes with logical AND rendering."], ["How should an optional details section be handled?", "Render it only when details exist", "Always show an empty heading", 0, "Conditional inclusion can avoid empty UI."], ["What should a conditional UI challenge test?", "Loading, empty, and error states too", "Only the ideal case", 0, "Boundary states help confirm the UI behaves correctly."]] ),
]);

export const renderingListsLessons = chapter("Learn React · Describing the UI", [
  uiTopic("react-rendering-lists-lesson", "Rendering Lists", "Turn collections of data into repeated UI and give each item a stable identity.", ["Many interfaces show repeated data such as messages, products, or menu links. Store the records in an array, then use JavaScript array methods to create the matching React elements.", "Filter the data before mapping when only some records should appear. Give each sibling element a key that remains connected to the same item as the collection changes."], ["const titles = ['Basics', 'Components'];\nreturn <ul>{titles.map(title => <li key={title}>{title}</li>)}</ul>;", "const cards = courses.map(course => <CourseCard key={course.id} course={course} />);", "const available = books.filter(book => book.inStock);"], [["Which array method turns each record into a UI element?", "map", "filter only", 0, "map transforms each item into a new value, such as JSX."], ["Which method selects only matching records?", "filter", "push", 0, "filter returns items that pass a condition."], ["What should a list key identify?", "The same item across renders", "The CSS theme", 0, "Stable keys help React track item identity as a list changes."]] ),
  uiTopic("react-list-map", "Rendering Data from Arrays", "Use map to transform records into components or elements.", ["The map method calls a function for every array item and returns a new array. In React, the callback can return JSX that displays that item's data.", "Use a component when each row has enough structure or behavior to deserve a named unit. Include a stable key on the top-level element returned for each item."], ["const names = ['Uma', 'Rafi'];\nreturn names.map(name => <li key={name}>{name}</li>);", "return products.map(product => <ProductRow key={product.id} product={product} />);", "const labels = lessons.map((lesson, index) => `${index + 1}. ${lesson.title}`);"], [["What does map return?", "A new array of transformed values", "The first matching item only", 0, "map returns an array with one transformed result for each input."], ["Where should a key go in a mapped component list?", "On the top-level element returned for each item", "Only on the inner text", 0, "The key identifies the sibling element React reconciles."], ["What is one benefit of a row component?", "It names a reusable unit of list UI", "It removes the need for data", 0, "A component can make repeated structure easier to maintain."]] ),
  uiTopic("react-list-filter", "Filtering Arrays of Items", "Select matching data before mapping it into the interface.", ["The filter method returns a new array containing only items whose predicate is true. You can then map that smaller collection to JSX.", "Keep filtering logic based on current data and controls. If the list is empty, consider showing a helpful empty-state message."], ["const active = users.filter(user => user.enabled);", "const results = items.filter(item => item.title.toLowerCase().includes(query.toLowerCase()));", "return active.map(user => <UserRow key={user.id} user={user} />);"], [["What does filter return?", "A new array of matching items", "A single changed item", 0, "filter keeps elements that satisfy its condition."], ["Which order works for a searchable list?", "Filter, then map", "Map to JSX, then filter the JSX strings", 0, "Filtering the data first keeps the render transformation clear."], ["What can improve an empty result?", "A clear no-results message", "An invisible list with no explanation", 0, "An empty state tells the user what happened or what to try."]] ),
  uiTopic("react-list-keys-order", "Keeping List Items in Order with Keys", "Provide stable keys so React can match each item as positions change.", ["When items are inserted, removed, or reordered, keys help React determine which rendered child corresponds to which data record.", "A key should remain with its item, not with the item's temporary position. Prefer IDs from the data model."], ["items.map(item => <li key={item.id}>{item.label}</li>)", "<Profile key={person.userId} person={person} />", "// Reordering items keeps each record's id unchanged."], [["What do keys help React track?", "Which item is which when a list changes", "The width of the browser", 0, "Keys connect rendered children to their data identity."], ["Which key source is usually best?", "A stable record ID", "A random number created every render", 0, "Stable IDs remain consistent for the same item."], ["What can go wrong if identity follows position?", "State can appear attached to the wrong item after reordering", "The list always disappears", 0, "Index-based identity can confuse reconciliation when order changes."]] ),
  uiTopic("react-list-key-source", "Where to Get Your Key", "Choose keys from stable data identifiers whenever possible.", ["A database ID, slug, or other persistent unique value is usually a good key. If the data has no stable identity, consider whether the data model should include one.", "Avoid generating random keys during render because they change every time. Indexes are suitable only for lists that truly never reorder or change membership."], ["<li key={article.slug}>{article.title}</li>", "<Row key={record.id} record={record} />", "// For a fixed, static sequence only: key={index} may be acceptable."], [["Which is a stable key candidate?", "A persistent item ID", "Math.random() during render", 0, "A persistent identifier stays with its record."], ["Why avoid a random key on every render?", "It makes every item look newly created", "It sorts the list", 0, "Changing keys causes React to recreate the element and can reset state."], ["When can an index key be acceptable?", "For a fixed list that will not reorder or change membership", "For every editable list", 0, "Indexes are only safe when positions are permanently stable."]] ),
  uiTopic("react-list-key-rules", "Rules of Keys", "Keep keys unique among siblings and stable across renders.", ["Keys only need to be unique within the current sibling list, not across the entire app. Use the same stable key for the same item whenever that list renders.", "The key is reserved for React and is not passed to the child as an ordinary prop. Pass the identifier separately if the child needs to use it."], ["<Row key={item.id} id={item.id} />", "<li key={`${group.id}-${item.id}`}>{item.name}</li>", "// Siblings in different lists may reuse the same key value."], [["Where must keys be unique?", "Among siblings in the same list", "Across every page in the app", 0, "Keys only need sibling-level uniqueness."], ["Can the child read key as a normal prop?", "No, pass another prop if needed", "Yes, automatically", 0, "React reserves key for its own reconciliation."], ["Should a key change for the same record on each render?", "No, it should stay stable", "Yes, to force updates", 0, "Stable keys let React preserve the item's identity."]] ),
  uiTopic("react-list-why-keys", "Why Does React Need Keys?", "Help React match old and new children efficiently and preserve the right state.", ["React compares the previous and next UI trees to update the browser. Keys help it recognize whether a child stayed, moved, was added, or was removed.", "Correct identity matters when list items have local state or focus. Without stable keys, React may reuse the wrong element after a reorder."], ["// Stable IDs let React match rows after sorting.", "// Adding an item at the start does not change other item identities.", "// Removing one record lets React remove its corresponding element."], [["What does a key help React decide?", "Which children were added, removed, moved, or kept", "Which API request to send", 0, "Keys help React match sibling elements between renders."], ["Why are keys especially important for stateful rows?", "They help state remain associated with the correct item", "They automatically save state to a database", 0, "Identity helps React preserve the correct component instance."], ["What does a key do for UI updates?", "Provides identity for reconciliation", "Adds visible text to the row", 0, "Keys guide React's comparison of list children."]] ),
  uiTopic("react-list-recap-challenges", "Recap and Challenges", "Build data-driven lists and test them under filtering and reordering.", ["Use filter to select records and map to render them. Give each mapped child a stable key based on its data identity.", "Try a searchable list with a no-results state, then sort it and remove an item. Check that labels, focus, and any row state remain connected to the right record."], ["const matches = tasks.filter(task => task.title.includes(query));", "return matches.map(task => <TaskRow key={task.id} task={task} />);", "return matches.length ? <TaskList tasks={matches} /> : <p>No matching tasks.</p>;"], [["What two array methods are central to data-driven lists?", "filter and map", "push and pop only", 0, "filter selects data and map transforms it to UI."], ["What should a key be based on?", "A stable identity in the data", "The current time", 0, "Keys should remain tied to the same record."], ["What should you test after adding search and sort?", "Reordering and empty results", "Only the default first row", 0, "Changing list membership and order tests key and empty-state behavior."]] ),
]);

export const pureComponentsLessons = chapter("Learn React · Describing the UI", [
  uiTopic("react-keeping-pure", "Keeping Components Pure", "Make rendering predictable by keeping calculations free from outside changes.", ["A pure function returns the same result for the same inputs and does not change values that existed before it ran. React components are expected to follow this pattern while rendering.", "Pure rendering makes components easier to test and lets React safely render work more than once. Put user-triggered changes in event handlers and synchronization with external systems in effects."], ["function double(value) { return value * 2; }", "function Welcome({ name }) { return <h1>Hello, {name}</h1>; }", "function Price({ amount, quantity }) { return <p>{amount * quantity}</p>; }"], [["What makes a function pure?", "Same inputs give the same output without outside mutation", "It changes a global value", 0, "Purity means predictable output and no mutation of existing outside values."], ["What should a component's render depend on?", "Its inputs and current state", "The time of day unless passed in", 0, "Rendering should be determined by the component's data."], ["Where should a user-triggered change happen?", "In an event handler", "During every render", 0, "Event handlers run in response to user actions."]] ),
  uiTopic("react-purity-formula", "Purity: Components as Formulas", "Think of rendering as a calculation from props and state to UI.", ["Like a formula, a component should produce a consistent UI when it receives the same props and state. This makes output easier to reason about.", "When a value changes, React calls the component again with the current inputs. Avoid hidden dependencies such as mutating shared data during render."], ["function Total({ price, count }) { return <p>{price * count}</p>; }", "function Greeting({ name }) { return <p>Hi, {name}</p>; }", "function Status({ online }) { return <span>{online ? 'Online' : 'Offline'}</span>; }"], [["What is the input to a component formula?", "Props and state", "The browser window color", 0, "React rendering uses component inputs and state."], ["What should the same inputs produce?", "The same UI result", "A random different result", 0, "Purity makes output predictable."], ["What can a hidden mutation cause?", "Unexpected output between renders", "A guaranteed faster build", 0, "Mutation changes data outside the calculation and can make results unpredictable."]] ),
  uiTopic("react-side-effects", "Side Effects: (Un)intended Consequences", "Keep external changes out of the render calculation.", ["A side effect changes something outside the function, such as writing to a global variable, changing the DOM directly, or sending a request. Doing this during render can cause repeated or surprising behavior.", "React may render a component more than once to prepare or check UI. Render should therefore stay safe to repeat."], ["// Avoid changing a global counter in the component body.", "// Avoid sending analytics directly during render.", "// Calculate a label from props without changing external state."], [["Which is a side effect?", "Writing to a global variable", "Multiplying two local numbers", 0, "A global write changes something outside the current calculation."], ["Why should render be safe to repeat?", "React may call components more than once", "The browser only supports one render", 0, "React can repeat rendering work as part of its model and checks."], ["Where should external synchronization happen?", "In an appropriate effect or event handler", "As an unconditional render action", 0, "Effects and event handlers are the right places for side effects."]] ),
  uiTopic("react-local-mutation", "Local Mutation: Your Component's Little Secret", "Distinguish safe local variables from changing data owned outside the component.", ["Creating and changing a new local object during a render calculation is usually safe because it does not alter data from a previous render. Mutating props, state, or shared objects is not safe.", "For state updates, create a new array or object rather than editing the existing one. This keeps previous values intact and helps React detect the change."], ["const options = [];\noptions.push('Newest'); // local value created in this render", "const next = [...items, newItem];", "// Avoid props.items.push(newItem);"], [["When is local mutation usually safe?", "When changing a fresh local value created in the function", "When changing shared props", 0, "A fresh local value is not shared with earlier renders."], ["How should a state array be updated?", "Create a new array", "Mutate the existing array", 0, "New arrays keep previous state snapshots unchanged."], ["Why avoid changing a prop object?", "The parent owns it and expects it to remain unchanged", "Props are always strings", 0, "Props are inputs that children should treat as read-only."]] ),
  uiTopic("react-side-effect-where", "Where You Can Cause Side Effects", "Run changes in response to a specific event or synchronize after rendering when needed.", ["Event handlers are a natural place for actions caused by a person, such as saving a form or adding an item. Effects are for synchronizing with external systems after the UI is rendered.", "Do not use an effect for a value that can be calculated from current props and state. Keeping derived values in render avoids extra state and synchronization."], ["function SaveButton() { return <button onClick={() => saveDraft()}>Save</button>; }", "useEffect(() => { document.title = title; }, [title]);", "const fullName = `${first} ${last}`; // derive directly"], [["Where should a save caused by a click happen?", "In the click event handler", "During every render", 0, "The event handler runs because the user asked to save."], ["What is an Effect suited for?", "Synchronizing with an external system", "Calculating every simple label", 0, "Effects connect rendered state to external systems."], ["Where should a value derived from props be calculated?", "During render", "In separate duplicated state", 0, "Derived values can be calculated directly from current inputs."]] ),
  uiTopic("react-purity-recap-challenges", "Recap and Challenges", "Practice finding and removing mutations and render-time side effects.", ["Pure components calculate UI from inputs without changing outside data. React can safely repeat that calculation, which helps avoid unpredictable results.", "Review a component body for global writes, prop mutation, or external requests. Move actions to handlers or effects and test that repeated renders keep the same output."], ["// Refactor: const sorted = [...items].sort(compare);", "// Move save() into onClick rather than calling it in render.", "// Calculate subtotal from cart items instead of storing a duplicate."], [["Which expression follows a pure-render pattern?", "A calculation based on props", "A global variable update", 0, "Calculations from inputs preserve render purity."], ["What should happen to a request triggered by a button?", "Start it from the event handler", "Start it on every render", 0, "User actions belong in event handlers."], ["What is a useful review challenge?", "Find mutation and move it to a safe update", "Add more global state", 0, "Removing mutation improves predictability."]] ),
]);

export const uiTreeLessons = chapter("Learn React · Describing the UI", [
  uiTopic("react-understanding-ui-tree", "Understanding Your UI as a Tree", "Use tree diagrams to reason about component relationships and rendered output.", ["A tree is a way to describe parent-child relationships. React components form a tree as parents render children, and React uses that structure to produce browser or native UI.", "Thinking in trees helps you trace data flow, find the owner of shared state, and understand which parts may render when an input changes."], ["App -> Header -> SearchBox", "App -> Main -> CourseList -> CourseCard", "// A parent-child tree can help locate a shared state owner."], [["What relationship does a component tree show?", "Parent and child components", "Only CSS colors", 0, "The tree models which components render other components."], ["How can a tree help debug state?", "It shows which components share an ancestor", "It lists image file sizes", 0, "The nearest shared ancestor is often where shared state belongs."], ["What can a parent render?", "One or more child components", "Only text nodes", 0, "Components compose by rendering child components."]] ),
  uiTopic("react-ui-tree", "Your UI as a Tree", "Follow the component hierarchy from the app root down to visible controls.", ["The root component is the starting point React renders for an app or route. Its children can render more children, creating a nested structure.", "The browser DOM is related to this structure but includes host elements such as div and button. Component trees focus on the React components that organize the UI."], ["App -> Layout -> Page", "Page -> Sidebar + Article", "Article -> Heading + Paragraph"], [["Where does a component tree begin?", "At a root component", "At a CSS declaration", 0, "A root component is the top-level component for that rendered tree."], ["Are browser elements like div the same as custom components?", "No, host elements and React components are different tree nodes", "Yes, they are identical", 0, "React components organize UI while host elements become DOM nodes."], ["What can a tree diagram help you trace?", "How a page is composed from nested parts", "The user's internet speed", 0, "The hierarchy shows the structure of the interface."]] ),
  uiTopic("react-render-tree", "The Render Tree", "Model which components appear in one particular render of the app.", ["A render tree shows the component instances rendered for a given set of props and state. Conditional rendering can change which children appear between render passes.", "The tree helps explain composition and possible update paths. It does not include every HTML tag; it focuses on component relationships."], ["App -> Dashboard -> ChartPanel", "App -> SignInPage when authenticated is false", "App -> Dashboard -> ChartPanel when authenticated is true"], [["What does a render tree represent?", "Components rendered for a particular UI state", "All files in the project", 0, "The render tree is tied to a rendered component structure."], ["Can conditional rendering change the tree?", "Yes, children can differ by data or state", "No, the tree never changes", 0, "Conditions can include or omit component branches."], ["Does the render tree show every HTML tag?", "No, it focuses on React component relationships", "Yes, every browser node is a component", 0, "Host DOM elements are not the same as custom component nodes."]] ),
  uiTopic("react-module-dependency-tree", "The Module Dependency Tree", "See how source files import and depend on other modules.", ["The module dependency tree describes which files import other files. It is different from the render tree: an imported component is not necessarily rendered on the current screen.", "Build tools use module dependencies to bundle code. This tree can help investigate app size, shared utilities, and where a dependency enters the project."], ["App.tsx imports Page.tsx", "Page.tsx imports Header.tsx and List.tsx", "List.tsx imports formatDate.ts"], [["What relationship does a module dependency tree show?", "Which modules import other modules", "Which buttons are visible", 0, "The dependency tree follows imports between source files."], ["Is every imported component necessarily rendered?", "No", "Yes, all imports display on screen", 0, "Importing a module does not guarantee it is used in the current render."], ["What can dependency trees help investigate?", "Bundle composition and dependency paths", "A component's background color only", 0, "Imports affect which code may be included in the build."]] ),
  uiTopic("react-ui-tree-recap", "Recap", "Use render and dependency trees to answer different questions about an app.", ["The render tree describes component relationships for a UI render. The module dependency tree describes source-level import relationships.", "Use the render tree to reason about composition and state ownership; use the dependency tree to trace imports and build composition."], ["// Render tree: App -> Page -> SearchResults", "// Dependency tree: SearchResults.tsx -> SearchBox.tsx", "// A file can be imported without appearing in the current render."], [["Which tree helps find component parents and children?", "The render tree", "The module dependency tree", 0, "The render tree models rendered component relationships."], ["Which tree follows import statements?", "The module dependency tree", "The DOM event tree", 0, "Module dependencies come from imports between files."], ["Why keep the two tree ideas separate?", "They describe different relationships", "They are always the same structure", 0, "Rendered UI and source imports answer different questions."]] ),
]);
